private static final class FakeSourceConduit extends AbstractStreamSourceConduit<StreamSourceConduit> {
    private final byte[] data;
    private final Deque<ByteBuffer> pushBackQueue;
    private int position;
    private int available;
    private boolean returnEof;
    private int forcedZeroReads;

    FakeSourceConduit(byte[] data, Deque<ByteBuffer> pushBackQueue) { super(null); ... }

    void feed(int count) { available = Math.min(data.length, available + count); }

    @Override public int read(ByteBuffer dst) {
        if (returnEof) return -1;
        if (forcedZeroReads > 0) { forcedZeroReads--; return 0; }
        int total = 0;
        ByteBuffer pushed = pushBackQueue.pollFirst();
        while (pushed != null) {
            int n = Math.min(pushed.remaining(), dst.remaining());
            ByteBuffer copy = pushed.duplicate();
            copy.limit(copy.position() + n);
            dst.put(copy);
            pushed.position(pushed.position() + n);
            total += n;
            if (pushed.hasRemaining()) { pushBackQueue.addFirst(pushed); break; }
            pushed = pushBackQueue.pollFirst();
            if (!dst.hasRemaining()) break;
        }
        if (dst.hasRemaining() && position < available) {
            int n = Math.min(dst.remaining(), available - position);
            dst.put(data, position, n);
            position += n;
            total += n;
        }
        return total;
    }

    @Override public long read(ByteBuffer[] dsts, int off, int len) { ... loop read(dsts[i]) ... }
}
```

