private static final class RecordingBufferWrapper implements ChunkedStreamSourceConduit.BufferWrapper {
    private final int bufferSize;
    final List<TestPooledBuffer> allocated = new ArrayList<>();
    final List<ByteBuffer> pushedBack = new ArrayList<>(); // snapshots
    final Deque<ByteBuffer> pushBackQueue = new ArrayDeque<>();

    RecordingBufferWrapper(int bufferSize) {...}

    @Override public PooledByteBuffer allocate() {
        TestPooledBuffer pooled = new TestPooledBuffer(bufferSize);
        allocated.add(pooled);
        return pooled;
    }
    @Override public void pushBack(PooledByteBuffer pooled) {
        ByteBuffer buffer = pooled.getBuffer();
        pushedBack.add(buffer.duplicate());
        pushBackQueue.addLast(buffer);
        ((TestPooledBuffer) pooled).pushedBack = true;
    }
}
