/**
 * Tests for {@link ChunkedStreamSourceConduit#read(ByteBuffer)}.
 *
 * <p>The source conduit (the "next" conduit) and the pooled buffer wrapper are faked so that
 * the observable behaviour of the de-chunking read can be verified: how many payload bytes are
 * copied into the destination, what is reported at the end of the chunked stream, which bytes
 * are pushed back, when the pooled buffer is released and when the finish listener fires.</p>
 */
public class ChunkedStreamSourceConduitReadTests {

    @Test
    public void readsSingleChunkPayloadAndReportsEndOfStream() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 16);
        fixture.feedAll();
        ByteBuffer dst = ByteBuffer.allocate(10);

        int read = fixture.conduit.read(dst);

        assertEquals(5, read);
        assertEquals("hello", contentOf(dst));
        // the chunk delimiter, the last-chunk header and the trailer terminator are pushed back
        assertEquals(1, fixture.wrapper.pushedBackContent.size());
        assertEquals("\r\n0\r\n\r\n", fixture.wrapper.pushedBackContent.get(0));
        assertEquals(1, fixture.wrapper.allocated.size());
        assertFalse(fixture.wrapper.allocated.get(0).closed,
                "a pushed back pooled buffer must not be closed");
        assertEquals(0, fixture.listener.count);
        assertEquals(0, fixture.closeable.closeCount);

        // the terminating chunk is already buffered, so this read reports the end of the stream
        ByteBuffer endDst = ByteBuffer.allocate(10);
        assertEquals(-1, fixture.conduit.read(endDst));
        assertEquals(0, endDst.position(), "no bytes may be written for the end of stream");
        assertEquals(1, fixture.listener.count);
        assertSame(fixture.conduit, fixture.listener.lastConduit);
        assertEquals(2, fixture.wrapper.allocated.size());
        assertTrue(fixture.wrapper.allocated.get(1).closed);

        // once the end of the stream was reported the listener must not fire again
        assertEquals(-1, fixture.conduit.read(ByteBuffer.allocate(10)));
        assertEquals(1, fixture.listener.count, "finish listener must only be invoked once");
        assertEquals(2, fixture.wrapper.allocated.size(),
                "no buffer may be allocated once the stream is finished");
    }

    @Test
    public void emptyChunkedStreamReportsEndOfStreamImmediately() throws IOException {
        Fixture fixture = new Fixture("0\r\n\r\n", 16);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(10);
        assertEquals(-1, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.listener.count);
        assertEquals(0, fixture.closeable.closeCount);

        assertEquals(-1, fixture.conduit.read(ByteBuffer.allocate(10)));
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void readsMultipleChunksAcrossChunkBoundaries() throws IOException {
        Fixture fixture = new Fixture("3\r\nabc\r\n3\r\ndef\r\n0\r\n\r\n", 32);
        fixture.feedAll();

        assertEquals("abcdef", readUntilEndOfStream(fixture, 32, 10));
        assertEquals(1, fixture.listener.count);
        assertEquals(0, fixture.closeable.closeCount);
    }

    @Test
    public void splitsPayloadWhenDestinationIsSmallerThanChunk() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 16);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(3);
        assertEquals(3, fixture.conduit.read(dst));
        assertEquals("hel", contentOf(dst));
        // the rest of the chunk (plus the following chunk framing) is pushed back for later reads
        assertFalse(fixture.wrapper.pushedBackContent.isEmpty());
        assertEquals("lo\r\n0\r\n\r\n", fixture.wrapper.pushedBackContent.get(0));

        assertEquals("hello", readUntilEndOfStream(fixture, 3, 10));
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void doesNotConsumeDataWhenDestinationHasNoRemainingSpace() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n", 16);
        fixture.feedAll();

        ByteBuffer dst = ByteBuffer.allocate(5);
        dst.position(5); // no space left in the destination

        assertEquals(0, fixture.conduit.read(dst));
        assertEquals(0, dst.remaining(), "nothing may be written into a full destination");
        assertEquals(1, fixture.wrapper.pushedBackContent.size());
        assertEquals("hello\r\n", fixture.wrapper.pushedBackContent.get(0),
                "the whole chunk payload must be kept for the next read");
        assertEquals(0, fixture.listener.count);

        // once space is available the very same payload is returned, nothing was lost
        dst.position(0);
        assertEquals(5, fixture.conduit.read(dst));
        assertEquals("hello", contentOf(dst));
    }

    @Test
    public void readsDirectlyFromSourceWhenPooledBufferIsExhausted() throws IOException {
        Fixture fixture = new Fixture("10\r\n0123456789abcdef\r\n0\r\n\r\n", 8);

        // header plus three payload bytes; the remaining payload is read directly into the destination
        fixture.feed(11);
        ByteBuffer dst = ByteBuffer.allocate(32);
        assertEquals(7, fixture.conduit.read(dst));
        assertEquals("0123456", contentOf(dst));
        assertEquals(32, dst.limit(), "the destination limit must be restored");

        fixture.feed(8);
        dst.clear();
        assertEquals(8, fixture.conduit.read(dst));
        assertEquals("789abcde", contentOf(dst));
        assertEquals(32, dst.limit());

        fixture.feed(1);
        dst.clear();
        assertEquals(1, fixture.conduit.read(dst));
        assertEquals("f", contentOf(dst));

        fixture.feedAll();
        assertEquals("0123456789abcdef", "0123456" + "789abcde" + "f"
                + readUntilEndOfStream(fixture, 32, 10));
        assertEquals(1, fixture.listener.count);
    }

    @Test
