        ByteBuffer dst = ByteBuffer.allocate(16);

        assertEquals(0, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.wrapper.allocated.size());
        assertTrue(fixture.wrapper.allocated.get(0).closed,
                "the buffer must be released when no data was read");
        assertEquals(0, fixture.listener.count);

        fixture.feed(8);
        assertEquals(5, fixture.conduit.read(dst));
        assertEquals("hello", contentOf(dst));

        fixture.feed(7);
        dst.clear();
        assertEquals(-1, fixture.conduit.read(dst));
        assertEquals(0, dst.position());
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void throwsClosedChannelExceptionWhenSourceReportsEof() throws IOException {
        Fixture fixture = new Fixture("5\r\nhello\r\n0\r\n\r\n", 16);
        fixture.next.setEof(true);

        assertThrows(ClosedChannelException.class, () -> fixture.conduit.read(ByteBuffer.allocate(16)));
        assertEquals(1, fixture.closeable.closeCount, "the channel must be closed on failure");
        assertEquals(1, fixture.wrapper.allocated.size());
        assertTrue(fixture.wrapper.allocated.get(0).closed);
        assertEquals(0, fixture.listener.count);
    }

    @Test
    public void throwsClosedChannelExceptionWhenSourceReportsEofMidChunk() throws IOException {
        Fixture fixture = new Fixture("5\r\nhel", 8);
        fixture.feed(6);
        fixture.next.setEof(true);

        ByteBuffer dst = ByteBuffer.allocate(32);
        assertThrows(ClosedChannelException.class, () -> fixture.conduit.read(dst));
        assertEquals("hel", contentOf(dst), "bytes read before the failure remain in the destination");
        assertEquals(1, fixture.closeable.closeCount);
    }

    @Test
    public void closesChannelWhenMaxEntitySizeIsExceeded() throws IOException {
        Fixture fixture = new Fixture("10\r\n0123456789abcdef\r\n0\r\n\r\n", 32, 5);
        fixture.feedAll();

        IOException thrown = assertThrows(IOException.class,
                () -> fixture.conduit.read(ByteBuffer.allocate(32)));
        assertTrue(thrown instanceof RequestTooBigException,
                "expected a RequestTooBigException but got " + thrown);
        assertTrue(thrown.getMessage().contains("5"), thrown.getMessage());
        assertEquals(1, fixture.closeable.closeCount);
        assertEquals(1, fixture.listener.count);
    }

    @Test
    public void throwsClosedChannelExceptionWhenReadAfterChannelWasClosed() throws IOException {
        Fixture fixture = new Fixture("10\r\n0123456789abcdef\r\n0\r\n\r\n", 32, 5);
        fixture.feedAll();
        assertThrows(IOException.class, () -> fixture.conduit.read(ByteBuffer.allocate(32)));
        int allocationsAfterFailure = fixture.wrapper.allocated.size();

        ClosedChannelException exception = assertThrows(ClosedChannelException.class,
                () -> fixture.conduit.read(ByteBuffer.allocate(32)));
        assertNotNull(exception.getMessage());
        assertEquals(allocationsAfterFailure, fixture.wrapper.allocated.size(),
                "a closed conduit must not allocate buffers");
        assertEquals(1, fixture.closeable.closeCount);
    }

    private static String readUntilEndOfStream(Fixture fixture, int destinationSize, int maxReads)
            throws IOException {
        StringBuilder result = new StringBuilder();
        ByteBuffer dst = ByteBuffer.allocate(destinationSize);
        for (int i = 0; i < maxReads; i++) {
            dst.clear();
            int read = fixture.conduit.read(dst);
            if (read == -1) {
                return result.toString();
            }
            assertTrue(read >= 0, "read must never return a negative value other than -1");
            result.append(contentOf(dst));
        }
        fail("end of stream was not reported within " + maxReads + " reads");
        return null;
    }

    private static String contentOf(ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        copy.flip();
        byte[] bytes = new byte[copy.remaining()];
        copy.get(bytes);
        return new String(bytes, StandardCharsets.ISO_8859_1);
    }

    /**
     * Creates a conduit together with its fakes. The chunked data is only handed to the source
     * conduit once {@link #feed(int)} has been called, which models data arriving from the socket.
     */
    private static final class Fixture {

        private final RecordingBufferWrapper wrapper;
        private final FakeSourceConduit next;
        private final RecordingConduitListener listener = new RecordingConduitListener();
        private final RecordingCloseable closeable = new RecordingCloseable();
        private final ChunkedStreamSourceConduit conduit;

        Fixture(String chunkedData, int bufferSize) {
            this(chunkedData, bufferSize, -1);
        }

        Fixture(String chunkedData, int bufferSize, long maxEntitySize) {
            byte[] data = chunkedData.getBytes(StandardCharsets.ISO_8859_1);
            this.wrapper = new RecordingBufferWrapper(bufferSize);
            this.next = new FakeSourceConduit(data, wrapper.pushBackQueue);
            HttpServerExchange exchange = maxEntitySize > 0 ? new HttpServerExchange(null, maxEntitySize) : null;
            this.conduit = new ChunkedStreamSourceConduit(next, wrapper, listener, null, exchange, closeable, null);
        }

        void feed(int count) {
            next.feed(count);
        }

        void feedAll() {
            next.feed(Integer.MAX_VALUE);
        }
    }

    private static final class RecordingBufferWrapper implements ChunkedStreamSourceConduit.BufferWrapper {

        private final int bufferSize;
        private final Deque<ByteBuffer> pushBackQueue = new ArrayDeque<>();
        private final List<TestPooledBuffer> allocated = new ArrayList<>();
        private final List<String> pushedBackContent = new ArrayList<>();

        RecordingBufferWrapper(int bufferSize) {
            this.bufferSize = bufferSize;
        }

        @Override
        public PooledByteBuffer allocate() {
            TestPooledBuffer pooled = new TestPooledBuffer(bufferSize);
            allocated.add(pooled);
            return pooled;
        }

        @Override
        public void pushBack(PooledByteBuffer pooled) {
            TestPooledBuffer testPooled = (TestPooledBuffer) pooled;
            pushedBackContent.add(contentOf(testPooled.buffer));
            pushBackQueue.addLast(testPooled.buffer);
        }
    }

    private static final class TestPooledBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean closed;

        TestPooledBuffer(int bufferSize) {
            this.buffer = ByteBuffer.allocate(bufferSize);
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            closed = true;
        }

        @Override
        public boolean isOpen() {
            return !closed;
        }
    }

    /**
     * A stream source conduit that behaves like a socket: it first drains buffers that were pushed
     * back and then hands out the bytes that have been "fed" so far.
     */
    private static final class FakeSourceConduit extends AbstractStreamSourceConduit<StreamSourceConduit> {

        private final byte[] data;
        private final Deque<ByteBuffer> pushBackQueue;
        private int position;
        private int available;
        private boolean eof;

        FakeSourceConduit(byte[] data, Deque<ByteBuffer> pushBackQueue) {
            super(null);
            this.data = data;
            this.pushBackQueue = pushBackQueue;
        }

        void feed(int count) {
            available = (int) Math.min(data.length, (long) available + count);
        }

        void setEof(boolean eof) {
            this.eof = eof;
        }

        @Override
        public int read(ByteBuffer dst) throws IOException {
            int total = 0;
            while (!pushBackQueue.isEmpty() && dst.hasRemaining()) {
                ByteBuffer pushed = pushBackQueue.peekFirst();
                int count = Math.min(pushed.remaining(), dst.remaining());
                ByteBuffer copy = pushed.duplicate();
                copy.limit(copy.position() + count);
                dst.put(copy);
                pushed.position(pushed.position() + count);
                total += count;
                if (!pushed.hasRemaining()) {
                    pushBackQueue.pollFirst();
                }
            }
            if (dst.hasRemaining() && position < available) {
                int count = Math.min(dst.remaining(), available - position);
                dst.put(data, position, count);
                position += count;
                total += count;
            }
            if (total == 0 && eof) {
                return -1;
            }
            return total;
        }

        @Override
        public long read(ByteBuffer[] dsts, int offset, int length) throws IOException {
            for (int i = offset; i < offset + length; i++) {
                if (dsts[i].hasRemaining()) {
                    return read(dsts[i]);
                }
            }
            return 0;
        }
    }

    private static final class RecordingConduitListener implements ConduitListener<ChunkedStreamSourceConduit> {

        private int count;
        private ChunkedStreamSourceConduit lastConduit;

        @Override
        public void handleEvent(ChunkedStreamSourceConduit channel) {
            count++;
            lastConduit = channel;
        }
    }

    private static final class RecordingCloseable implements Closeable {

        private int closeCount;

        @Override
        public void close() {
            closeCount++;
        }
    }
}
