    private static String readUntilEndOfStream(Fixture fixture, int destinationSize, int maxReads)
            throws IOException {
        StringBuilder result = new StringBuilder();
        ByteBuffer dst = ByteBuffer.allocate(destinationSize);
        for (int i = 0; i < maxReads; i++) {
            dst.clear();
            int read = fixture.conduit.read(dst);
            if (read == -1) {
