package io.undertow.protocols.http2;

import io.undertow.util.HeaderMap;
import io.undertow.util.HttpString;
import org.junit.jupiter.api.Test;

import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for {@link HpackEncoder#encode(HeaderMap, ByteBuffer)}.
 *
 * <p>The expected byte sequences are the HPACK (RFC 7541) representations of the encoded headers:
 * a single byte with the high bit set for an exact static table match, a {@code 0x40} prefixed
 * literal with incremental indexing, a {@code 0x10} prefixed literal that must never be indexed,
 * a {@code 0x20} prefixed table size update and a {@code 0x80} prefixed dynamic table reference.
 * The first dynamic table entry has index 62 because the HPACK static table has 61 entries.</p>
 */
public class HpackEncoderEncodeTests {

    private static final int DEFAULT_MAX_TABLE_SIZE = 4096;

    private static final byte[] LITERAL_X_FOO_BAR = bytes(0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r');

    private static final HpackEncoder.HpackHeaderFunction NO_INDEXING_NO_HUFFMAN = function(false, false);

    private static final HpackEncoder.HpackHeaderFunction HUFFMAN_NO_INDEXING = function(false, true);

    @Test
    public void emptyHeaderMapProducesNoBytes() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer target = ByteBuffer.allocate(64);

        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(new HeaderMap(), target));
        assertEquals(0, target.position());
    }

    @Test
    public void exactStaticTableMatchesEncodeToASingleIndexByte() {
        // :method: GET -> static table index 2
        assertEncoded(bytes(0x82), headers(":method", "GET"));
        // :path: / -> static table index 4
        assertEncoded(bytes(0x84), headers(":path", "/"));
        // :status: 200 -> static table index 8
        assertEncoded(bytes(0x88), headers(":status", "200"));
        // accept-encoding: gzip, deflate -> static table index 16
        assertEncoded(bytes(0x90), headers("accept-encoding", "gzip, deflate"));
    }

    @Test
    public void staticNameWithUnknownValueUsesLiteralWithIncrementalIndexing() {
        // 0x40 | 2 (name index of :method) followed by the literal value "PUT"
        assertEncoded(bytes(0x42, 0x03, 'P', 'U', 'T'), headers(":method", "PUT"));
    }

    @Test
    public void staticNameWithUnknownValueUsesNeverIndexedLiteralWhenIndexingIsDisabled() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, NO_INDEXING_NO_HUFFMAN);
        // 0x10 | 2 (name index of :method) followed by the literal value "PUT"
        assertEncoded(encoder, bytes(0x12, 0x03, 'P', 'U', 'T'), headers(":method", "PUT"));
    }

    @Test
    public void unknownHeaderNameUsesLiteralWithIncrementalIndexing() {
        // 0x40, name length 5 + "x-foo", value length 3 + "bar"
        assertEncoded(LITERAL_X_FOO_BAR, headers("x-foo", "bar"));
    }

    @Test
    public void unknownHeaderNameUsesNeverIndexedLiteralWhenIndexingIsDisabled() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, NO_INDEXING_NO_HUFFMAN);
        assertEncoded(encoder, bytes(0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
    }

    @Test
    public void zeroMaxTableSizeDisablesDynamicIndexing() {
        HpackEncoder encoder = new HpackEncoder(0);
        assertEncoded(encoder, bytes(0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
    }

    @Test
    public void headerNameIsLowercasedOnTheWire() {
        assertEncoded(bytes(0x40, 0x07, 'x', '-', 'u', 'p', 'p', 'e', 'r', 0x01, 'V'),
                headers("X-Upper", "V"));
    }

