        assertEncoded(bytes(0x1f, 0x0d, 0x02, '4', '2'), headers("content-length", "42"));
    }

    @Test
    public void staticTableLookupIsCaseInsensitive() {
        assertEncoded(bytes(0x1f, 0x0d, 0x02, '4', '2'), headers("Content-Length", "42"));
