    }

    @Test
    public void repeatedValueIsReferencedThroughTheDynamicTable() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        HeaderMap headers = headers("x-foo", "bar");

        ByteBuffer first = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, first));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(first), () -> "first encoding was " + hexOf(first));

        // 0x80 | 62 : the entry added by the first call is the first dynamic table entry
        ByteBuffer second = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, second));
        assertArrayEquals(bytes(0xbe), bytesOf(second), () -> "second encoding was " + hexOf(second));
    }

    @Test
    public void dynamicTableEntryIsReusedByASubsequentHeaderMap() {
