    @Test
    public void huffmanEncodedNameAndValueDecodeBackToTheOriginalHeader() throws Exception {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, HUFFMAN_NO_INDEXING);
        ByteBuffer target = ByteBuffer.allocate(128);

        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-huff", "aaaaaaaaaaa"), target));

        ByteBuffer view = readView(target);
        // literal header field never indexed, with a new (huffman encoded) name
        assertEquals(0x10, view.get() & 0xff);
        assertEquals("x-huff", readString(view));
        assertEquals("aaaaaaaaaaa", readString(view));
        assertFalse(view.hasRemaining());
