    @Test
    public void setMaxTableSizeEmitsASingleTableSizeUpdate() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        encoder.setMaxTableSize(512);

        // 0x20 | 31 followed by the continuation octets of 512 - 31
        ByteBuffer update = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(new HeaderMap(), update));
        assertArrayEquals(bytes(0x3f, 0xe1, 0x03), bytesOf(update), () -> "update was " + hexOf(update));

        // the update is only sent once
        ByteBuffer next = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers(":method", "GET"), next));
        assertArrayEquals(bytes(0x82), bytesOf(next), () -> "next encoding was " + hexOf(next));
    }

    @Test
    public void multipleTableSizeChangesEmitTheMinimumAndTheFinalSize() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        encoder.setMaxTableSize(512);
        encoder.setMaxTableSize(4096);

        ByteBuffer target = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers(":method", "GET"), target));
        assertArrayEquals(bytes(0x3f, 0xe1, 0x03, 0x3f, 0xe1, 0x1f, 0x82), bytesOf(target),
                () -> "encoding was " + hexOf(target));
    }

    @Test
    public void tableSizeUpdateAffectsTheIndexingDecision() {
        // x-foo: bar needs 32 + 5 + 3 = 40 octets of table space
        HpackEncoder tooSmall = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        tooSmall.setMaxTableSize(40);
        assertEncoded(tooSmall, bytes(0x3f, 0x09, 0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));

        HpackEncoder bigEnough = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        bigEnough.setMaxTableSize(41);
        assertEncoded(bigEnough, bytes(0x3f, 0x0a, 0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
        assertEncoded(bigEnough, bytes(0xbe), headers("x-foo", "bar"));
    }

    @Test
    public void oldestDynamicTableEntryIsEvictedWhenTheTableIsFull() {
        // each entry needs 32 + 5 + 3 = 40 octets, so a 50 octet table can only hold one of them
        HpackEncoder encoder = new HpackEncoder(50);
        HeaderMap first = headers("x-aaa", "bbb");

        ByteBuffer firstTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(first, firstTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'a', 'a', 'a', 0x03, 'b', 'b', 'b'),
                bytesOf(firstTarget), () -> "first encoding was " + hexOf(firstTarget));

        ByteBuffer secondTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-ccc", "ddd"), secondTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'c', 'c', 'c', 0x03, 'd', 'd', 'd'),
                bytesOf(secondTarget), () -> "second encoding was " + hexOf(secondTarget));

        // the first entry has been evicted, so it has to be sent literally again
        ByteBuffer thirdTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(first, thirdTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'a', 'a', 'a', 0x03, 'b', 'b', 'b'),
                bytesOf(thirdTarget), () -> "third encoding was " + hexOf(thirdTarget));
    }

    @Test
    public void overflowIsReturnedOnlyWhenTheBufferIsSmallerThanTheRequiredSize() {
        // x-foo: bar requires 11 + 5 + 1 + 3 = 20 octets of room (the encoding itself needs 11)
        HeaderMap exact = headers("x-foo", "bar");
        HpackEncoder exactEncoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer exactTarget = ByteBuffer.allocate(20);
        assertEquals(HpackEncoder.State.COMPLETE, exactEncoder.encode(exact, exactTarget));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(exactTarget), () -> "encoding was " + hexOf(exactTarget));

        HeaderMap tooSmall = headers("x-foo", "bar");
        HpackEncoder overflowEncoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer tooSmallTarget = ByteBuffer.allocate(19);
        assertEquals(HpackEncoder.State.OVERFLOW, overflowEncoder.encode(tooSmall, tooSmallTarget));
        assertEquals(0, tooSmallTarget.position());

        ByteBuffer resumeTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, overflowEncoder.encode(tooSmall, resumeTarget));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(resumeTarget), () -> "resumed encoding was " + hexOf(resumeTarget));
    }

    @Test
    public void overflowAfterPseudoHeadersIsResumedForTheRemainingHeaders() {
        HeaderMap headers = headers(":method", "GET");
        headers.put(new HttpString("x-very-long-header-name"), "value");

        HpackEncoder reference = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer referenceTarget = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, reference.encode(headers, referenceTarget));

        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        // large enough for the pseudo header (which is encoded first) but not for the regular header
        ByteBuffer firstTarget = ByteBuffer.allocate(30);
        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, firstTarget));
        assertArrayEquals(bytes(0x82), bytesOf(firstTarget), () -> "first encoding was " + hexOf(firstTarget));

        ByteBuffer secondTarget = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, secondTarget));

        ByteBuffer combined = ByteBuffer.allocate(referenceTarget.position());
        ByteBuffer firstView = readView(firstTarget);
        combined.put(firstView);
        combined.put(readView(secondTarget));
