    @Test
    public void pendingOverflowRejectsADifferentHeaderMap() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        HeaderMap headers = headers("x-foo", "bar");

        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, ByteBuffer.allocate(0)));

        assertThrows(IllegalStateException.class, () -> encoder.encode(new HeaderMap(), ByteBuffer.allocate(128)));
    }

    private static void assertEncoded(byte[] expected, HeaderMap headers) {
        assertEncoded(new HpackEncoder(DEFAULT_MAX_TABLE_SIZE), expected, headers);
    }

    private static void assertEncoded(HpackEncoder encoder, byte[] expected, HeaderMap headers) {
        ByteBuffer target = ByteBuffer.allocate(256);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, target));
        assertArrayEquals(expected, bytesOf(target), () -> "encoding was " + hexOf(target));
    }

    private static HeaderMap headers(String name, String value) {
        HeaderMap headers = new HeaderMap();
        headers.put(new HttpString(name), value);
        return headers;
    }

    private static HpackEncoder.HpackHeaderFunction function(final boolean index, final boolean huffman) {
        return new HpackEncoder.HpackHeaderFunction() {
            @Override
            public boolean shouldUseIndexing(HttpString header, String value) {
                return index;
            }

            @Override
            public boolean shouldUseHuffman(HttpString header, String value) {
                return huffman;
            }

            @Override
            public boolean shouldUseHuffman(HttpString header) {
                return huffman;
            }
        };
    }

    private static byte[] bytes(int... values) {
        byte[] result = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            result[i] = (byte) values[i];
        }
        return result;
    }

    private static byte[] bytesOf(ByteBuffer target) {
        byte[] result = new byte[target.position()];
        for (int i = 0; i < result.length; i++) {
            result[i] = target.get(i);
        }
        return result;
    }

    private static ByteBuffer readView(ByteBuffer target) {
        ByteBuffer view = target.duplicate();
        view.flip();
        return view;
    }

    private static String hexOf(ByteBuffer target) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < target.position(); i++) {
            builder.append(String.format("%02x ", target.get(i) & 0xff));
        }
        return builder.toString();
    }

    private static String readString(ByteBuffer source) throws HpackException {
        int lengthOctet = source.get(source.position()) & 0xff;
        boolean huffman = (lengthOctet & 0x80) != 0;
        int length = Hpack.decodeInteger(source, 7);
        StringBuilder result = new StringBuilder();
        if (huffman) {
            HPackHuffman.decode(source, length, result);
        } else {
            for (int i = 0; i < length; i++) {
                result.append((char) (source.get() & 0xff));
            }
        }
        return result.toString();
    }
}
