package io.undertow.protocols.http2;

import io.undertow.util.HeaderMap;
import io.undertow.util.HttpString;
import org.junit.jupiter.api.Test;

import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for {@link HpackEncoder#encode(HeaderMap, ByteBuffer)}.
 *
 * <p>The expected byte sequences are the HPACK (RFC 7541) representations of the encoded headers:
 * a single byte with the high bit set for an exact static table match, a {@code 0x40} prefixed
 * literal with incremental indexing, a {@code 0x10} prefixed literal that must never be indexed,
 * a {@code 0x20} prefixed table size update and a {@code 0x80} prefixed dynamic table reference.
 * The first dynamic table entry has index 62 because the HPACK static table has 61 entries.</p>
 */
public class HpackEncoderEncodeTests {

    private static final int DEFAULT_MAX_TABLE_SIZE = 4096;

    private static final byte[] LITERAL_X_FOO_BAR = bytes(0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r');

    private static final HpackEncoder.HpackHeaderFunction NO_INDEXING_NO_HUFFMAN = function(false, false);

    private static final HpackEncoder.HpackHeaderFunction HUFFMAN_NO_INDEXING = function(false, true);

    @Test
    public void emptyHeaderMapProducesNoBytes() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer target = ByteBuffer.allocate(64);

        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(new HeaderMap(), target));
        assertEquals(0, target.position());
    }

    @Test
    public void exactStaticTableMatchesEncodeToASingleIndexByte() {
        // :method: GET -> static table index 2
        assertEncoded(bytes(0x82), headers(":method", "GET"));
        // :path: / -> static table index 4
        assertEncoded(bytes(0x84), headers(":path", "/"));
        // :status: 200 -> static table index 8
        assertEncoded(bytes(0x88), headers(":status", "200"));
        // accept-encoding: gzip, deflate -> static table index 16
        assertEncoded(bytes(0x90), headers("accept-encoding", "gzip, deflate"));
    }

    @Test
    public void staticNameWithUnknownValueUsesLiteralWithIncrementalIndexing() {
        // 0x40 | 2 (name index of :method) followed by the literal value "PUT"
        assertEncoded(bytes(0x42, 0x03, 'P', 'U', 'T'), headers(":method", "PUT"));
    }

    @Test
    public void staticNameWithUnknownValueUsesNeverIndexedLiteralWhenIndexingIsDisabled() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, NO_INDEXING_NO_HUFFMAN);
        // 0x10 | 2 (name index of :method) followed by the literal value "PUT"
        assertEncoded(encoder, bytes(0x12, 0x03, 'P', 'U', 'T'), headers(":method", "PUT"));
    }

    @Test
    public void unknownHeaderNameUsesLiteralWithIncrementalIndexing() {
        // 0x40, name length 5 + "x-foo", value length 3 + "bar"
        assertEncoded(LITERAL_X_FOO_BAR, headers("x-foo", "bar"));
    }

    @Test
    public void unknownHeaderNameUsesNeverIndexedLiteralWhenIndexingIsDisabled() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, NO_INDEXING_NO_HUFFMAN);
        assertEncoded(encoder, bytes(0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
    }

    @Test
    public void zeroMaxTableSizeDisablesDynamicIndexing() {
        HpackEncoder encoder = new HpackEncoder(0);
        assertEncoded(encoder, bytes(0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
    }

    @Test
    public void headerNameIsLowercasedOnTheWire() {
        assertEncoded(bytes(0x40, 0x07, 'x', '-', 'u', 'p', 'p', 'e', 'r', 0x01, 'V'),
                headers("X-Upper", "V"));
    }

    @Test
    public void connectionSpecificHeadersAreSkipped() {
        HeaderMap headers = headers("connection", "keep-alive");
        headers.put(new HttpString("Transfer-Encoding"), "chunked");
        headers.put(new HttpString("KEEP-ALIVE"), "timeout=5");
        headers.put(new HttpString("upgrade"), "h2c");

        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer target = ByteBuffer.allocate(128);

        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, target));
        assertEquals(0, target.position());
    }

    @Test
    public void connectionSpecificHeadersDoNotPreventOtherHeadersFromBeingEncoded() {
        HeaderMap headers = headers("connection", "keep-alive");
        headers.put(new HttpString("transfer-encoding"), "chunked");
        headers.put(new HttpString("x-foo"), "bar");

        assertEncoded(LITERAL_X_FOO_BAR, headers);
    }

    @Test
    public void contentLengthIsEncodedAsNeverIndexedLiteralWithNameIndex() {
        // content-length is not indexed by the default header function; 0x10 | 15 with the
        // continuation byte 0x0d encodes static table index 28
        assertEncoded(bytes(0x1f, 0x0d, 0x02, '4', '2'), headers("content-length", "42"));
    }

    @Test
    public void staticTableLookupIsCaseInsensitive() {
        assertEncoded(bytes(0x1f, 0x0d, 0x02, '4', '2'), headers("Content-Length", "42"));
    }

    @Test
    public void staticNameWithUnknownIndexableValueKeepsTheNameIndex() {
        // content-type is indexable, so the literal uses incremental indexing with name index 31
        assertEncoded(bytes(0x5f, 0x0a, 't', 'e', 'x', 't', '/', 'p', 'l', 'a', 'i', 'n'),
                headers("Content-Type", "text/plain"));
    }

    @Test
    public void emptyValueIsEncodedAsZeroLengthValue() {
        assertEncoded(bytes(0x40, 0x07, 'x', '-', 'e', 'm', 'p', 't', 'y', 0x00), headers("x-empty", ""));
    }

    @Test
    public void repeatedValueIsReferencedThroughTheDynamicTable() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        HeaderMap headers = headers("x-foo", "bar");

        ByteBuffer first = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, first));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(first), () -> "first encoding was " + hexOf(first));

        // 0x80 | 62 : the entry added by the first call is the first dynamic table entry
        ByteBuffer second = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, second));
        assertArrayEquals(bytes(0xbe), bytesOf(second), () -> "second encoding was " + hexOf(second));
    }

    @Test
    public void dynamicTableEntryIsReusedByASubsequentHeaderMap() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);

        ByteBuffer first = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-foo", "bar"), first));

        HeaderMap next = headers("x-foo", "bar");
        next.put(new HttpString(":method"), "GET");
        ByteBuffer second = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(next, second));
        // the pseudo header is encoded first (static index 2), the regular header is a dynamic reference
        assertArrayEquals(bytes(0x82, 0xbe), bytesOf(second), () -> "second encoding was " + hexOf(second));
    }

    @Test
    public void changedValueForAKnownNameIsEncodedAgain() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);

        ByteBuffer first = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-foo", "bar"), first));

        // a different value can not be referenced by index, but the name is not in the static table
        // either, so the whole literal is repeated
        ByteBuffer second = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-foo", "baz"), second));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'z'),
                bytesOf(second), () -> "second encoding was " + hexOf(second));
    }

    @Test
    public void pseudoHeadersAreEncodedBeforeRegularHeaders() {
        HeaderMap headers = headers("x-foo", "bar");
        headers.put(new HttpString(":method"), "GET");

        assertEncoded(bytes(0x82, 0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'), headers);
    }

    @Test
    public void multipleValuesForTheSameHeaderAreEncodedInOrder() {
        HeaderMap headers = headers("x-multi", "a");
        headers.add(new HttpString("x-multi"), "bb");
        headers.add(new HttpString("x-multi"), "ccc");

        assertEncoded(bytes(
                0x40, 0x07, 'x', '-', 'm', 'u', 'l', 't', 'i', 0x01, 'a',
                0x40, 0x07, 'x', '-', 'm', 'u', 'l', 't', 'i', 0x02, 'b', 'b',
                0x40, 0x07, 'x', '-', 'm', 'u', 'l', 't', 'i', 0x03, 'c', 'c', 'c'), headers);
    }

    @Test
    public void carriageReturnAndLineFeedInValuesAreReplacedWithSpaces() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, NO_INDEXING_NO_HUFFMAN);
        assertEncoded(encoder, bytes(0x10, 0x06, 'x', '-', 'c', 'r', 'l', 'f', 0x04, 'a', ' ', ' ', 'b'),
                headers("x-crlf", "a\r\nb"));
    }

    @Test
    public void longValueIsHuffmanEncoded() {
        // the value length octet 0x87 has the huffman bit set and announces 7 bytes for
        // eleven 'a' characters (five bits each, padded with ones)
        assertEncoded(bytes(0x40, 0x06, 'x', '-', 'h', 'u', 'f', 'f', 0x87,
                0x18, 0xc6, 0x31, 0x8c, 0x63, 0x18, 0xc7), headers("x-huff", "aaaaaaaaaaa"));
    }

    @Test
    public void longHeaderNameIsHuffmanEncodedWhenEnabled() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, HUFFMAN_NO_INDEXING);
        assertEncoded(encoder, bytes(0x10, 0x85, 0xf2, 0xb4, 0xf6, 0xcb, 0x2f, 0x87,
                0x18, 0xc6, 0x31, 0x8c, 0x63, 0x18, 0xc7), headers("x-huff", "aaaaaaaaaaa"));
    }

    @Test
    public void huffmanEncodedNameAndValueDecodeBackToTheOriginalHeader() throws Exception {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE, HUFFMAN_NO_INDEXING);
        ByteBuffer target = ByteBuffer.allocate(128);

        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-huff", "aaaaaaaaaaa"), target));

        ByteBuffer view = readView(target);
        // literal header field never indexed, with a new (huffman encoded) name
        assertEquals(0x10, view.get() & 0xff);
        assertEquals("x-huff", readString(view));
        assertEquals("aaaaaaaaaaa", readString(view));
        assertFalse(view.hasRemaining());
    }

    @Test
    public void setMaxTableSizeEmitsASingleTableSizeUpdate() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        encoder.setMaxTableSize(512);

        // 0x20 | 31 followed by the continuation octets of 512 - 31
        ByteBuffer update = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(new HeaderMap(), update));
        assertArrayEquals(bytes(0x3f, 0xe1, 0x03), bytesOf(update), () -> "update was " + hexOf(update));

        // the update is only sent once
        ByteBuffer next = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers(":method", "GET"), next));
        assertArrayEquals(bytes(0x82), bytesOf(next), () -> "next encoding was " + hexOf(next));
    }

    @Test
    public void multipleTableSizeChangesEmitTheMinimumAndTheFinalSize() {
        HpackEncoder encoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        encoder.setMaxTableSize(512);
        encoder.setMaxTableSize(4096);

        ByteBuffer target = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers(":method", "GET"), target));
        assertArrayEquals(bytes(0x3f, 0xe1, 0x03, 0x3f, 0xe1, 0x1f, 0x82), bytesOf(target),
                () -> "encoding was " + hexOf(target));
    }

    @Test
    public void tableSizeUpdateAffectsTheIndexingDecision() {
        // x-foo: bar needs 32 + 5 + 3 = 40 octets of table space
        HpackEncoder tooSmall = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        tooSmall.setMaxTableSize(40);
        assertEncoded(tooSmall, bytes(0x3f, 0x09, 0x10, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));

        HpackEncoder bigEnough = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        bigEnough.setMaxTableSize(41);
        assertEncoded(bigEnough, bytes(0x3f, 0x0a, 0x40, 0x05, 'x', '-', 'f', 'o', 'o', 0x03, 'b', 'a', 'r'),
                headers("x-foo", "bar"));
        assertEncoded(bigEnough, bytes(0xbe), headers("x-foo", "bar"));
    }

    @Test
    public void oldestDynamicTableEntryIsEvictedWhenTheTableIsFull() {
        // each entry needs 32 + 5 + 3 = 40 octets, so a 50 octet table can only hold one of them
        HpackEncoder encoder = new HpackEncoder(50);
        HeaderMap first = headers("x-aaa", "bbb");

        ByteBuffer firstTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(first, firstTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'a', 'a', 'a', 0x03, 'b', 'b', 'b'),
                bytesOf(firstTarget), () -> "first encoding was " + hexOf(firstTarget));

        ByteBuffer secondTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers("x-ccc", "ddd"), secondTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'c', 'c', 'c', 0x03, 'd', 'd', 'd'),
                bytesOf(secondTarget), () -> "second encoding was " + hexOf(secondTarget));

        // the first entry has been evicted, so it has to be sent literally again
        ByteBuffer thirdTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(first, thirdTarget));
        assertArrayEquals(bytes(0x40, 0x05, 'x', '-', 'a', 'a', 'a', 0x03, 'b', 'b', 'b'),
                bytesOf(thirdTarget), () -> "third encoding was " + hexOf(thirdTarget));
    }

    @Test
    public void overflowIsReturnedOnlyWhenTheBufferIsSmallerThanTheRequiredSize() {
        // x-foo: bar requires 11 + 5 + 1 + 3 = 20 octets of room (the encoding itself needs 11)
        HeaderMap exact = headers("x-foo", "bar");
        HpackEncoder exactEncoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer exactTarget = ByteBuffer.allocate(20);
        assertEquals(HpackEncoder.State.COMPLETE, exactEncoder.encode(exact, exactTarget));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(exactTarget), () -> "encoding was " + hexOf(exactTarget));

        HeaderMap tooSmall = headers("x-foo", "bar");
        HpackEncoder overflowEncoder = new HpackEncoder(DEFAULT_MAX_TABLE_SIZE);
        ByteBuffer tooSmallTarget = ByteBuffer.allocate(19);
        assertEquals(HpackEncoder.State.OVERFLOW, overflowEncoder.encode(tooSmall, tooSmallTarget));
        assertEquals(0, tooSmallTarget.position());

        ByteBuffer resumeTarget = ByteBuffer.allocate(128);
        assertEquals(HpackEncoder.State.COMPLETE, overflowEncoder.encode(tooSmall, resumeTarget));
        assertArrayEquals(LITERAL_X_FOO_BAR, bytesOf(resumeTarget), () -> "resumed encoding was " + hexOf(resumeTarget));
    }

