        for (int i = 0; i < result.length; i++) {
            result[i] = target.get(i);
        }
        return result;
    }

    private static ByteBuffer readView(ByteBuffer target) {
        ByteBuffer view = target.duplicate();
        view.flip();
        return view;
    }

    private static String hexOf(ByteBuffer target) {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < target.position(); i++) {
            builder.append(String.format("%02x ", target.get(i) & 0xff));
        }
        return builder.toString();
    }

    private static String readString(ByteBuffer source) throws HpackException {
        int lengthOctet = source.get(source.position()) & 0xff;
        boolean huffman = (lengthOctet & 0x80) != 0;
        int length = Hpack.decodeInteger(source, 7);
        StringBuilder result = new StringBuilder();
        if (huffman) {
            HPackHuffman.decode(source, length, result);
        } else {
            for (int i = 0; i < length; i++) {
                result.append((char) (source.get() & 0xff));
            }
        }
        return result.toString();
    }
