             lastAssignedStreamOtherSide = lastGoodStreamId;
        }
    } else if (isClient()) {
        // client received push promise => update the last assigned for the client
        lastAssignedStreamOtherSide = Math.max(lastAssignedStreamOtherSide, streamNo);
    }
}

