            if (http2SettingsMaxHeaderListSize > 0) {
                return Math.min(Math.min(HTTP2_MAX_HEADER_SIZE, maxHeaderSizeConfig), http2SettingsMaxHeaderListSize);
            } else {
                return Math.min(HTTP2_MAX_HEADER_SIZE, maxHeaderSizeConfig);
            }
        } else {
