    @Test
    public void dataFrameSendsProtocolErrorAndLeavesFrameDataUntouched() throws Exception {
        TestHttp2Channel channel = newChannel();
        Http2FrameHeaderParser header = frameHeader(channel, Http2Channel.FRAME_TYPE_DATA, 0, 1, 5);
        TrackingPooledByteBuffer frameData = frameData();

        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(header, frameData);

        assertNull(result);
        assertEquals(List.of(Http2Channel.ERROR_PROTOCOL_ERROR), channel.goAwayStatuses);
        assertTrue(frameData.isOpen(), "DATA frames are dropped before the buffer is handed to a stream");
    }

    @Test
    public void pingAckClosesFrameDataAndDoesNotReply() throws Exception {
        TestHttp2Channel channel = newChannel();
        byte[] payload = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
        Http2PingParser pingParser = pingParser(payload);
        Http2FrameHeaderParser header = frameHeader(channel, Http2Channel.FRAME_TYPE_PING,
                Http2Channel.PING_FLAG_ACK, 0, Http2Channel.PING_FRAME_LENGTH);
        header.parser = pingParser;
        TrackingPooledByteBuffer frameData = frameData();

        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(header, frameData);

        Http2PingStreamSourceChannel ping = assertInstanceOf(Http2PingStreamSourceChannel.class, result);
        assertTrue(ping.isAck());
        assertArrayEquals(payload, ping.getData());
        assertTrue(channel.sentPings.isEmpty(), "An ACK ping must not be acknowledged again");
        assertFalse(frameData.isOpen());
    }

    @Test
