    private static void putHolder(TestHttp2Channel channel, int streamId, Http2StreamSourceChannel source)
            throws Exception {
        Class<?> holderClass = Class.forName("io.undertow.protocols.http2.Http2Channel$StreamHolder");
        Constructor<?> constructor = holderClass.getDeclaredConstructor(Http2StreamSourceChannel.class);
        constructor.setAccessible(true);
