    private static Object getField(Object target, String name) throws Exception {
        return findField(target.getClass(), name).get(target);
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        findField(target.getClass(), name).set(target, value);
    }

    private static int getIntField(Object target, String name) throws Exception {
        return findField(target.getClass(), name).getInt(target);
    }

    private static boolean getBooleanField(Object target, String name) throws Exception {
        return findField(target.getClass(), name).getBoolean(target);
    }

    private static Field findField(Class<?> type, String name) throws NoSuchFieldException {
        for (Class<?> current = type; current != null; current = current.getSuperclass()) {
            try {
                Field field = current.getDeclaredField(name);
                field.setAccessible(true);
                return field;
            } catch (NoSuchFieldException ignored) {
                // Continue with the superclass.
            }
        }
        throw new NoSuchFieldException(name);
    }

    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {
        private final ByteBuffer buffer;
        private boolean open = true;

        private TrackingPooledByteBuffer(ByteBuffer buffer) {
            this.buffer = buffer;
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            open = false;
        }

        @Override
        public boolean isOpen() {
            return open;
        }
    }

