        setFlowControlWindow(sink, 50);
        ByteBuffer data = setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        Frame frame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(50, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(0, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(50, header.getRemainingInBuffer());
        assertEquals(50, data.remaining(), "the unsent part of the body must remain in the body buffer");
    }

    @Test
    void dataFrameIsLimitedToTheMaximumFrameSize() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        ByteBuffer data = setBody(sink, 20000);

        SendFrameHeader header = createFrameHeader(sink);

        Frame frame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(Http2Channel.DEFAULT_MAX_FRAME_SIZE, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(0, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(20000 - Http2Channel.DEFAULT_MAX_FRAME_SIZE, header.getRemainingInBuffer());

        // the window is consumed by the amount that is actually being sent
        long sent = Http2Channel.DEFAULT_MAX_FRAME_SIZE;
        assertEquals(65535 - sent, streamFlowControlWindow(sink),
                "the stream flow control window must be decremented by the amount that is sent");
    }

    // ---------------------------------------------------------------------------------------------
    // plain data frames
    // ---------------------------------------------------------------------------------------------

    @Test
    void writesDataFrameForTheWholeBufferedBody() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        ByteBuffer data = setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        PooledByteBuffer frameBuffer = header.getByteBuffer();
        assertNotNull(frameBuffer);
        assertEquals(9, frameBuffer.getBuffer().remaining(), "a non padded data frame header is 9 bytes");
        Frame frame = readFrameHeader(frameBuffer.getBuffer());
        assertEquals(100, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(0, frame.flags, "neither END_STREAM nor PADDED must be set");
        assertEquals(STREAM_ID, frame.streamId);

        assertEquals(0, header.getRemainingInBuffer());
        assertNull(header.getTrailer());
        assertEquals(100, data.remaining());
        assertEquals(65535 - 100, streamFlowControlWindow(sink));
    }

    @Test
    void finalFrameSetsEndStreamOnTheDataFrame() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFinalFrameQueued(sink, true);
        setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        Frame frame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(100, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(Http2Channel.DATA_FLAG_END_STREAM, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(0, header.getRemainingInBuffer());
        assertNull(header.getTrailer());
    }

    @Test
    void emptyBufferWithoutFinalFrameProducesAnEmptyHeader() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setBody(sink, 0);

        SendFrameHeader header = createFrameHeader(sink);

        assertNotNull(header.getByteBuffer());
        assertEquals(0, header.getByteBuffer().getBuffer().remaining(), "no frame must be generated");
        assertEquals(0, header.getRemainingInBuffer());
        assertNull(header.getTrailer());
        assertFalse(header.isAnotherFrameRequired());
    }

    // ---------------------------------------------------------------------------------------------
    // padding handling
    // ---------------------------------------------------------------------------------------------

    @Test
    void paddingIsSentWhenTheWindowHasRoomForIt() throws Exception {
        TestHttp2Channel channel = newChannel(10);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        assertEquals(1 + 9, frameBuffer.remaining(), "the padding length octet is part of the frame header");
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(1 + 100 + 10, frame.length, "padding length octet + data + padding");
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(Http2Channel.DATA_FLAG_PADDED, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(10, frameBuffer.get() & 0xFF, "padding length octet");

        assertEquals(0, header.getRemainingInBuffer());
        ByteBuffer trailer = header.getTrailer();
        assertNotNull(trailer, "the padding bytes are sent after the body");
        assertEquals(10, trailer.remaining());
        while (trailer.hasRemaining()) {
            assertEquals(0, trailer.get(), "padding bytes are zero");
        }
    }

    @Test
    void paddingIsReducedToOneByteWhenTheWindowOnlyCoversThePadding() throws Exception {
        // body of 20 bytes, padding of 20 bytes and a window of 21 bytes: the padding is dropped down to a
        // single byte so that at least one byte of data can be sent
        TestHttp2Channel channel = newChannel(20);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFlowControlWindow(sink, 21);
        ByteBuffer data = setBody(sink, 20);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(21, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(Http2Channel.DATA_FLAG_PADDED, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(1, frameBuffer.get() & 0xFF, "padding is reduced to a single byte");

        assertEquals(1, header.getRemainingInBuffer());
        assertNotNull(header.getTrailer());
        assertEquals(1, header.getTrailer().remaining());
        assertEquals(19, data.remaining(), "19 of the 20 bytes are sent");
    }

    @Test
    void paddingIsShrunkSoThatTheWholeBodyFitsTheWindow() throws Exception {
        // body of 5 bytes, padding of 20 bytes, window of 15 bytes: 9 padding bytes are kept so that the
        // final frame still counts as a final frame
        TestHttp2Channel channel = newChannel(20);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFlowControlWindow(sink, 15);
        setFinalFrameQueued(sink, true);
        setBody(sink, 5);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(15, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(Http2Channel.DATA_FLAG_END_STREAM | Http2Channel.DATA_FLAG_PADDED, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(9, frameBuffer.get() & 0xFF);

        assertEquals(0, header.getRemainingInBuffer());
        assertNotNull(header.getTrailer());
        assertEquals(9, header.getTrailer().remaining());
    }

    @Test
    void paddingIsDroppedWhenTheBodyAlreadyFillsTheWindow() throws Exception {
        TestHttp2Channel channel = newChannel(20);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFlowControlWindow(sink, 10);
        ByteBuffer data = setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        assertEquals(9, frameBuffer.remaining(), "no padding length octet must be written");
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(10, frame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, frame.type);
        assertEquals(0, frame.flags, "padding is dropped completely");
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(90, header.getRemainingInBuffer());
        assertNull(header.getTrailer());
        assertEquals(90, data.remaining());
    }

    // ---------------------------------------------------------------------------------------------
    // header block (first frame)
    // ---------------------------------------------------------------------------------------------

    @Test
    void firstFrameWritesTheHeaderBlockAndClearsTheFirstFlag() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        Http2DataStreamSinkChannel sink = newSink(channel, headers);
        setBody(sink, 0);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, frame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_HEADERS, frame.flags,
                "the whole header block fits in the frame, so END_HEADERS must be set");
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(frameBuffer.remaining(), frame.length, "the header block must be part of the frame");
        assertTrue(frame.length > 0, "the encoded header block must not be empty");

        // a second invocation must not produce a header block again
        PooledByteBuffer secondHeader = createFrameHeader(sink).getByteBuffer();
        buffersToRelease.add(secondHeader);
        assertEquals(0, secondHeader.getBuffer().remaining(),
                "only the first frame of the stream carries the header block");
    }

    @Test
    void firstFrameSetsEndStreamWhenTheResponseEndsWithoutData() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        Http2DataStreamSinkChannel sink = newSink(channel, headers);
        setFinalFrameQueued(sink, true);
        setBody(sink, 0);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, frame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_STREAM | Http2Channel.HEADERS_FLAG_END_HEADERS, frame.flags);
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(0, header.getRemainingInBuffer());
    }

    @Test
    void firstFrameWritesTheDataFrameAfterTheHeaderBlock() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        Http2DataStreamSinkChannel sink = newSink(channel, headers);
        ByteBuffer data = setBody(sink, 50);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame headersFrame = readFrameHeader(frameBuffer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, headersFrame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_HEADERS, headersFrame.flags);
        assertEquals(STREAM_ID, headersFrame.streamId);
        frameBuffer.position(frameBuffer.position() + headersFrame.length);

        Frame dataFrame = readFrameHeader(frameBuffer);
        assertEquals(50, dataFrame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, dataFrame.type);
        assertEquals(0, dataFrame.flags);
        assertEquals(STREAM_ID, dataFrame.streamId);

        assertEquals(0, header.getRemainingInBuffer());
        assertEquals(50, data.remaining());
    }

    // ---------------------------------------------------------------------------------------------
    // trailers
    // ---------------------------------------------------------------------------------------------

    @Test
    void trailersAreWrittenAfterAZeroLengthFinalDataFrame() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFinalFrameQueued(sink, true);
        HeaderMap trailers = new HeaderMap();
        trailers.put(new HttpString("x-trailer"), "value");
        sink.setTrailersProducer(() -> trailers);
        setBody(sink, 0);

        SendFrameHeader header = createFrameHeader(sink);

        Frame dataFrame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(0, dataFrame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, dataFrame.type);
        assertEquals(0, dataFrame.flags, "END_STREAM belongs to the trailers HEADERS frame");
        assertEquals(STREAM_ID, dataFrame.streamId);

        ByteBuffer trailer = header.getTrailer();
        assertNotNull(trailer);
        Frame trailerFrame = readFrameHeader(trailer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, trailerFrame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_STREAM | Http2Channel.HEADERS_FLAG_END_HEADERS,
                trailerFrame.flags);
        assertEquals(STREAM_ID, trailerFrame.streamId);
        assertEquals(trailer.remaining(), trailerFrame.length);
        assertTrue(trailerFrame.length > 0, "the encoded trailers must not be empty");
        assertEquals(0, header.getRemainingInBuffer());
    }

    @Test
    void dataFrameOfAFinalFrameWithTrailersHasNoEndStreamFlag() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFinalFrameQueued(sink, true);
        HeaderMap trailers = new HeaderMap();
        trailers.put(new HttpString("x-trailer"), "value");
        sink.setTrailersProducer(() -> trailers);
        setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        Frame dataFrame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(100, dataFrame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, dataFrame.type);
        assertEquals(0, dataFrame.flags, "the END_STREAM flag must be sent on the trailers frame instead");
        assertEquals(STREAM_ID, dataFrame.streamId);

        ByteBuffer trailer = header.getTrailer();
        assertNotNull(trailer);
        Frame trailerFrame = readFrameHeader(trailer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, trailerFrame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_STREAM | Http2Channel.HEADERS_FLAG_END_HEADERS,
                trailerFrame.flags);
        assertEquals(STREAM_ID, trailerFrame.streamId);
    }

    @Test
    void emptyTrailersAreIgnored() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        setFinalFrameQueued(sink, true);
        sink.setTrailersProducer(HeaderMap::new);
        setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        assertNull(header.getTrailer(), "an empty trailer map must be treated as no trailers at all");
        Frame dataFrame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(100, dataFrame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, dataFrame.type);
        assertEquals(Http2Channel.DATA_FLAG_END_STREAM, dataFrame.flags);
        assertEquals(0, header.getRemainingInBuffer());
    }

    @Test
    void trailersAreNotReadWhenTheFrameIsNotTheFinalFrame() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        Http2DataStreamSinkChannel sink = newSink(channel);
        setFirstFrame(sink, false);
        final boolean[] asked = {false};
        sink.setTrailersProducer(() -> {
            asked[0] = true;
            HeaderMap map = new HeaderMap();
            map.put(new HttpString("x-trailer"), "value");
            return map;
        });
        setBody(sink, 100);

        SendFrameHeader header = createFrameHeader(sink);

        assertFalse(asked[0], "trailers must only be requested for the final frame");
        assertNull(header.getTrailer());
        Frame dataFrame = readFrameHeader(header.getByteBuffer().getBuffer());
        assertEquals(Http2Channel.FRAME_TYPE_DATA, dataFrame.type);
        assertEquals(0, dataFrame.flags);
    }

    // ---------------------------------------------------------------------------------------------
    // helpers
    // ---------------------------------------------------------------------------------------------

    /**
     * {@link Http2Channel} subclass that gives full control over the number of padding bytes, which is
     * randomly generated from the configured padding size otherwise.
     */
    static final class TestHttp2Channel extends Http2Channel {

        private final int padding;
        private final List<StreamConnection> connections = new ArrayList<>();

        TestHttp2Channel(StreamConnection connection, int padding) {
            super(connection, "h2", bufferPool, null, false, false, false, OptionMap.EMPTY);
            this.padding = padding;
        }

        @Override
        int getPaddingBytes() {
            return padding;
        }
    }

    private TestHttp2Channel newChannel(int padding) throws Exception {
        ChannelPipe<StreamConnection, StreamConnection> pipe = worker.createFullDuplexPipeConnection();
        openConnections.add(pipe.getLeftSide());
        openConnections.add(pipe.getRightSide());
        return new TestHttp2Channel(pipe.getLeftSide(), padding);
    }

    private final List<StreamConnection> openConnections = new ArrayList<>();

    private Http2DataStreamSinkChannel newSink(Http2Channel channel) {
        return newSink(channel, new HeaderMap());
    }

    private Http2DataStreamSinkChannel newSink(Http2Channel channel, HeaderMap headers) {
        return new Http2DataStreamSinkChannel(channel, STREAM_ID, headers, Http2Channel.FRAME_TYPE_HEADERS);
    }

    private SendFrameHeader createFrameHeader(Http2DataStreamSinkChannel sink) throws Exception {
        Method method = Http2DataStreamSinkChannel.class.getDeclaredMethod("createFrameHeaderImpl");
        method.setAccessible(true);
        SendFrameHeader header = (SendFrameHeader) method.invoke(sink);
        if (header.getByteBuffer() != null) {
            buffersToRelease.add(header.getByteBuffer());
        }
        return header;
    }

    private static void setFirstFrame(Http2DataStreamSinkChannel sink, boolean first) throws Exception {
        setField(sink, Http2DataStreamSinkChannel.class, "first", first);
    }

    private static void setFinalFrameQueued(Http2DataStreamSinkChannel sink, boolean finalFrame) throws Exception {
        setField(sink, AbstractFramedStreamSinkChannel.class, "finalFrameQueued", finalFrame);
    }

    private static void setFlowControlWindow(Http2DataStreamSinkChannel sink, int window) throws Exception {
        setField(sink, Http2StreamSinkChannel.class, "flowControlWindow", window);
    }

    private static int streamFlowControlWindow(Http2DataStreamSinkChannel sink) throws Exception {
        Field field = Http2StreamSinkChannel.class.getDeclaredField("flowControlWindow");
        field.setAccessible(true);
        return field.getInt(sink);
    }

    private static ByteBuffer setBody(Http2DataStreamSinkChannel sink, int size) throws Exception {
        ByteBuffer data = ByteBuffer.allocate(Math.max(size, 1));
        data.limit(size);
        setField(sink, AbstractFramedStreamSinkChannel.class, "body",
                new ImmediatePooledByteBuffer(data));
        return data;
    }

    private static void setField(Object target, Class<?> type, String name, Object value) throws Exception {
        Field field = type.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Frame readFrameHeader(ByteBuffer buffer) {
        int b0 = buffer.get() & 0xFF;
        int b1 = buffer.get() & 0xFF;
        int b2 = buffer.get() & 0xFF;
        int type = buffer.get() & 0xFF;
        int flags = buffer.get() & 0xFF;
        int streamId = buffer.getInt() & 0x7FFFFFFF;
        return new Frame((b0 << 16) | (b1 << 8) | b2, type, flags, streamId);
    }

    private static final class Frame {
        private final int length;
        private final int type;
        private final int flags;
        private final int streamId;

        private Frame(int length, int type, int flags, int streamId) {
            this.length = length;
            this.type = type;
            this.flags = flags;
            this.streamId = streamId;
        }
    }
}
