        private final int padding;
        private final List<StreamConnection> connections = new ArrayList<>();

        TestHttp2Channel(StreamConnection connection, int padding) {
            super(connection, "h2", bufferPool, null, false, false, false, OptionMap.EMPTY);
            this.padding = padding;
        }

        @Override
        int getPaddingBytes() {
