    // ---------------------------------------------------------------------------------------------

    @Test
    void firstFrameWritesTheHeaderBlockAndClearsTheFirstFlag() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        Http2DataStreamSinkChannel sink = newSink(channel, headers);
        setBody(sink, 0);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame frame = readFrameHeader(frameBuffer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, frame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_HEADERS, frame.flags,
                "the whole header block fits in the frame, so END_HEADERS must be set");
        assertEquals(STREAM_ID, frame.streamId);
        assertEquals(frameBuffer.remaining(), frame.length, "the header block must be part of the frame");
        assertTrue(frame.length > 0, "the encoded header block must not be empty");

        // a second invocation must not produce a header block again
        PooledByteBuffer secondHeader = createFrameHeader(sink).getByteBuffer();
        buffersToRelease.add(secondHeader);
        assertEquals(0, secondHeader.getBuffer().remaining(),
                "only the first frame of the stream carries the header block");
    }

