    }

    @Test
    void firstFrameWritesTheDataFrameAfterTheHeaderBlock() throws Exception {
        TestHttp2Channel channel = newChannel(0);
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        Http2DataStreamSinkChannel sink = newSink(channel, headers);
        ByteBuffer data = setBody(sink, 50);

        SendFrameHeader header = createFrameHeader(sink);

        ByteBuffer frameBuffer = header.getByteBuffer().getBuffer();
        Frame headersFrame = readFrameHeader(frameBuffer);
        assertEquals(Http2Channel.FRAME_TYPE_HEADERS, headersFrame.type);
        assertEquals(Http2Channel.HEADERS_FLAG_END_HEADERS, headersFrame.flags);
        assertEquals(STREAM_ID, headersFrame.streamId);
        frameBuffer.position(frameBuffer.position() + headersFrame.length);

        Frame dataFrame = readFrameHeader(frameBuffer);
        assertEquals(50, dataFrame.length);
        assertEquals(Http2Channel.FRAME_TYPE_DATA, dataFrame.type);
        assertEquals(0, dataFrame.flags);
        assertEquals(STREAM_ID, dataFrame.streamId);

        assertEquals(0, header.getRemainingInBuffer());
        assertEquals(50, data.remaining());
    }

