    private SendFrameHeader createFrameHeader(Http2DataStreamSinkChannel sink) throws Exception {
        Method method = Http2DataStreamSinkChannel.class.getDeclaredMethod("createFrameHeaderImpl");
        method.setAccessible(true);
        SendFrameHeader header = (SendFrameHeader) method.invoke(sink);
        if (header.getByteBuffer() != null) {
            buffersToRelease.add(header.getByteBuffer());
        }
        return header;
