import java.net.SocketAddress;
import java.nio.ByteBuffer;

public class Exp2 {

    static class FakeConnection extends StreamConnection {
        FakeConnection(XnioIoThread thread) {
            super(thread);
            setSourceConduit(new EmptyStreamSourceConduit(thread));
            setSinkConduit(new NullStreamSinkConduit(thread));
        }
        @Override public SocketAddress getPeerAddress() { return null; }
        @Override public SocketAddress getLocalAddress() { return null; }
        @Override protected void notifyWriteClosed() {}
        @Override protected void notifyReadClosed() {}
        void invokeCloseListener() {}
    }

    static class RecordingChannel extends Http2Channel {
        int goAway = -1;
        RecordingChannel(StreamConnection c) {
            super(c, null, new DefaultByteBufferPool(false, 1024), null, false, false, true, OptionMap.EMPTY);
        }
        @Override public void sendGoAway(int status) {
            goAway = status;
        }
    }

    static ByteBuffer frame(int length, int type, int flags, int streamId, byte[] payload) {
        ByteBuffer buf = ByteBuffer.allocate(9 + (payload == null ? 0 : payload.length));
        buf.put((byte) ((length >> 16) & 0xff)).put((byte) ((length >> 8) & 0xff)).put((byte) (length & 0xff));
        buf.put((byte) type).put((byte) flags);
        buf.put((byte) ((streamId >> 24) & 0xff)).put((byte) ((streamId >> 16) & 0xff)).put((byte) ((streamId >> 8) & 0xff)).put((byte) (streamId & 0xff));
        if (payload != null) buf.put(payload);
        buf.flip();
        return buf;
    }

    public static void main(String[] args) throws Exception {
        XnioWorker worker = org.xnio.Xnio.getInstance().createWorker(OptionMap.EMPTY);
        try {
            RecordingChannel channel = new RecordingChannel(new FakeConnection(worker.getIoThread()));

            // 1 headers length 0 end_headers
            Http2FrameHeaderParser p = new Http2FrameHeaderParser(channel, null);
            System.out.println("1 headers end: " + p.handle(frame(0, 1, 4, 1, null)) + " parser=" + p.getParser().getClass().getSimpleName() + " cont=" + p.getContinuationParser() + " frameLen=" + p.getFrameLength());

            // 2 headers length 0 no end_headers, then continuation
            Http2FrameHeaderParser p2 = new Http2FrameHeaderParser(channel, null);
            System.out.println("2 headers no-end: " + p2.handle(frame(0, 1, 0, 1, null)) + " cont=" + (p2.getContinuationParser() == p2.getParser()));
            Http2FrameHeaderParser p2b = new Http2FrameHeaderParser(channel, p2.getContinuationParser());
            System.out.println("2b continuation: " + p2b.handle(frame(0, 9, 4, 1, null)) + " cont=" + p2b.getContinuationParser());

            // 2c continuation mismatched stream id
            Http2FrameHeaderParser p2c = new Http2FrameHeaderParser(channel, p2.getContinuationParser());
            channel.goAway = -1;
            try {
                p2c.handle(frame(0, 9, 4, 3, null));
            } catch (Throwable t) {
                System.out.println("2c " + t.getClass().getName() + " msg=" + t.getMessage() + " goAway=" + channel.goAway);
            }

            // 2d continuation with no continuation parser
            Http2FrameHeaderParser p2d = new Http2FrameHeaderParser(channel, null);
            channel.goAway = -1;
            try {
                p2d.handle(frame(0, 9, 4, 1, null));
            } catch (Throwable t) {
                System.out.println("2d " + t.getClass().getName() + " msg=" + t.getMessage() + " goAway=" + channel.goAway);
            }

            // 2e headers while continuation expected
            Http2FrameHeaderParser p2e = new Http2FrameHeaderParser(channel, p2.getContinuationParser());
            try {
                p2e.handle(frame(0, 1, 4, 1, null));
            } catch (Throwable t) {
                System.out.println("2e " + t.getClass().getName() + " code=" + ((ConnectionErrorException) t).getCode() + " msg=" + t.getMessage());
            }

            // 3 push promise no end headers
            Http2FrameHeaderParser p3 = new Http2FrameHeaderParser(channel, null);
            try {
                p3.handle(frame(4, 5, 0, 1, new byte[]{0, 0, 0, 2}));
            } catch (Throwable t) {
                System.out.println("3 " + t.getClass().getName() + " msg=" + t.getMessage());
            }

            // 4 push promise with end headers
            Http2FrameHeaderParser p4 = new Http2FrameHeaderParser(channel, null);
            System.out.println("4 push end: " + p4.handle(frame(4, 5, 4, 1, new byte[]{0, 0, 0, 2})) + " parser=" + p4.getParser().getClass().getSimpleName() + " cont=" + p4.getContinuationParser());

            // 5 data padded bad padding
            Http2FrameHeaderParser p5 = new Http2FrameHeaderParser(channel, null);
            try {
                p5.handle(frame(2, 0, 0x8, 1, new byte[]{5, 0}));
            } catch (Throwable t) {
                System.out.println("5 " + t.getClass().getName() + " code=" + ((t instanceof ConnectionErrorException) ? ((ConnectionErrorException) t).getCode() : -1));
            }

            // 6 discard
            Http2FrameHeaderParser p6 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b6 = frame(3, 10, 0, 0, new byte[]{1, 2, 3});
            System.out.println("6 unknown: " + p6.handle(b6) + " parser=" + p6.getParser().getClass().getSimpleName() + " remaining=" + b6.remaining());

            // 7 reserved bit
            Http2FrameHeaderParser p7 = new Http2FrameHeaderParser(channel, null);
            ByteBuffer b7 = frame(0, 4, 0, 0x80000001, null);
