/**
 * Unit tests for {@link Http2FrameHeaderParser#handle(ByteBuffer)}.
 *
 * <p>The tests exercise the frame header parsing state machine: partial headers, every supported
 * frame type (including the validation rules and their error codes), the continuation frame
 * bookkeeping and the observable side effects (goaway frames sent, parsers created/retained).</p>
 */
public class Http2FrameHeaderParserHandleTests {

    private static final int END_STREAM = Http2Channel.DATA_FLAG_END_STREAM;
    private static final int PADDED = Http2Channel.DATA_FLAG_PADDED;
    private static final int END_HEADERS = Http2Channel.HEADERS_FLAG_END_HEADERS;

    private static XnioWorker worker;

    private RecordingHttp2Channel channel;

    @BeforeAll
    public static void createWorker() throws IOException {
        worker = Xnio.getInstance().createWorker(OptionMap.EMPTY);
    }

    @AfterAll
    public static void stopWorker() {
        if (worker != null) {
            worker.shutdownNow();
        }
    }

    @BeforeEach
    public void createChannel() {
        channel = new RecordingHttp2Channel(new FakeStreamConnection(worker.getIoThread()));
    }

    // ---------------------------------------------------------------------------------------------
    // header parsing / partial frames
    // ---------------------------------------------------------------------------------------------

    @Test
    public void handleWithEmptyBufferReturnsFalse() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertFalse(parser.handle(ByteBuffer.allocate(0)));
        assertNull(parser.getParser(), "no parser may be created before the frame header is complete");
        assertEquals(0, parser.read);
    }

    @Test
    public void handleIncompleteHeaderReturnsFalseAndKeepsReadState() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertFalse(parser.handle(ByteBuffer.wrap(new byte[]{0, 0, 0, Http2Channel.FRAME_TYPE_SETTINGS, 0, 0, 0, 0})));
        assertNull(parser.getParser());
        assertEquals(8, parser.read);

        // the last header byte is supplied by the next read
        assertTrue(parser.handle(ByteBuffer.wrap(new byte[]{0})));
        assertEquals(9, parser.read);
        assertInstanceOf(Http2SettingsParser.class, parser.getParser());
    }

    @Test
    public void handleParsesHeaderFields() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        // WINDOW_UPDATE keeps the frame length for the parser itself, so no payload is required
        assertTrue(parser.handle(frame(4, Http2Channel.FRAME_TYPE_WINDOW_UPDATE, 0x5a, 0x00000007, new byte[]{0, 0, 0, 1})));

        assertEquals(4, parser.length);
        assertEquals(Http2Channel.FRAME_TYPE_WINDOW_UPDATE, parser.type);
        assertEquals(0x5a, parser.flags);
        assertEquals(7, parser.streamId);
        assertEquals(4, parser.getActualLength());
    }

    @Test
    public void handleParsesThreeByteLengthIntoLengthField() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(0x010203, Http2Channel.FRAME_TYPE_DATA, 0, 1, new byte[0])));

        assertEquals(0x010203, parser.length);
        assertEquals(0x010203, parser.getActualLength());
    }

    @Test
    public void handleMasksReservedBitOfStreamId() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(4, Http2Channel.FRAME_TYPE_WINDOW_UPDATE, 0, 0x80000003, new byte[]{0, 0, 0, 1})));

        assertEquals(3, parser.streamId);
    }

    // ---------------------------------------------------------------------------------------------
    // DATA
    // ---------------------------------------------------------------------------------------------

    @Test
    public void handleDataFrameWithZeroStreamIdThrowsProtocolError() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
                () -> parser.handle(frame(3, Http2Channel.FRAME_TYPE_DATA, 0, 0, new byte[]{1, 2, 3})));

        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, exception.getCode());
        assertTrue(exception.getMessage().contains("stream id must not be zero"));
        assertNull(parser.getParser(), "the frame parser must not be created for an invalid frame");
    }

    @Test
    public void handleDataFrameCreatesDataFrameParserAndLeavesPayload() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);
        ByteBuffer buffer = frame(3, Http2Channel.FRAME_TYPE_DATA, END_STREAM, 5, new byte[]{11, 12, 13});

        assertTrue(parser.handle(buffer));

        assertInstanceOf(Http2DataFrameParser.class, parser.getParser());
        assertEquals(3, parser.getFrameLength(), "data frames report their length to the framed channel");
        assertEquals(3, buffer.remaining(), "the payload is consumed by the stream itself");
        assertNull(parser.getContinuationParser());
    }

    @Test
    public void handleDataFrameWithPaddingRecordsPaddingLength() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(4, Http2Channel.FRAME_TYPE_DATA, PADDED, 1, new byte[]{2, 9, 9, 9})));

        Http2DataFrameParser dataFrameParser = assertInstanceOf(Http2DataFrameParser.class, parser.getParser());
        assertEquals(2, dataFrameParser.getPadding());
    }

    @Test
    public void handleDataFrameWithPaddingLargerThanPayloadThrowsProtocolError() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
                () -> parser.handle(frame(2, Http2Channel.FRAME_TYPE_DATA, PADDED, 1, new byte[]{5, 0})));

        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, exception.getCode());
    }

    @Test
    public void handleEmptyDataFrameFinishesImmediately() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(0, Http2Channel.FRAME_TYPE_DATA, 0, 1, new byte[0])));
        assertEquals(0, parser.getFrameLength());
    }

    // ---------------------------------------------------------------------------------------------
    // HEADERS / CONTINUATION
    // ---------------------------------------------------------------------------------------------

    @Test
    public void handleHeadersFrameWithZeroStreamIdThrowsProtocolError() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
                () -> parser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, END_HEADERS, 0, new byte[0])));

        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, exception.getCode());
        assertTrue(exception.getMessage().contains("stream id must not be zero"));
    }

    @Test
    public void handleHeadersFrameWithEndHeadersFlagDoesNotRecordContinuation() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, END_HEADERS, 1, new byte[0])));

        assertInstanceOf(Http2HeadersParser.class, parser.getParser());
        assertNull(parser.getContinuationParser());
        assertEquals(0, parser.getFrameLength(), "only data frames report a frame length");
    }

    @Test
    public void handleHeadersFrameWithoutEndHeadersFlagRecordsContinuation() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, 0, 1, new byte[0])));

        assertNotNull(parser.getContinuationParser());
        assertSame(parser.getParser(), parser.getContinuationParser());
    }

    @Test
    public void handleNonContinuationFrameWhileContinuationExpectedThrowsProtocolError() throws IOException {
        Http2FrameHeaderParser headersParser = new Http2FrameHeaderParser(channel, null);
        headersParser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, 0, 1, new byte[0]));

        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, headersParser.getContinuationParser());

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
                () -> parser.handle(frame(0, Http2Channel.FRAME_TYPE_DATA, 0, 1, new byte[0])));

        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, exception.getCode());
        assertTrue(exception.getMessage().contains("continuation frame"));
        assertNull(parser.getParser());
    }

    @Test
    public void handleContinuationFrameWithEndHeadersFlagClearsContinuationParser() throws IOException {
        Http2FrameHeaderParser headersParser = new Http2FrameHeaderParser(channel, null);
        headersParser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, 0, 1, new byte[0]));
        Http2HeadersParser continuation = headersParser.getContinuationParser();
        assertNotNull(continuation);

        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, continuation);
        assertTrue(parser.handle(frame(0, Http2Channel.FRAME_TYPE_CONTINUATION, END_HEADERS, 1, new byte[0])));

        assertSame(continuation, parser.getParser(), "the headers parser is continued");
        assertNull(parser.getContinuationParser());
        assertEquals(-1, channel.goAwayStatus, "no goaway may be sent for a correct continuation frame");
    }

    @Test
    public void handleContinuationFrameWithoutEndHeadersFlagKeepsContinuationParser() throws IOException {
        Http2FrameHeaderParser headersParser = new Http2FrameHeaderParser(channel, null);
        headersParser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, 0, 1, new byte[0]));
        Http2HeadersParser continuation = headersParser.getContinuationParser();
        assertNotNull(continuation);

        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, continuation);
        assertTrue(parser.handle(frame(0, Http2Channel.FRAME_TYPE_CONTINUATION, 0, 1, new byte[0])));

        assertSame(continuation, parser.getContinuationParser());
    }

    @Test
    public void handleContinuationFrameWithoutExpectedContinuationSendsGoAwayAndThrows() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        IOException exception = assertThrows(IOException.class,
                () -> parser.handle(frame(0, Http2Channel.FRAME_TYPE_CONTINUATION, END_HEADERS, 1, new byte[0])));

        assertEquals(IOException.class, exception.getClass());
        assertTrue(exception.getMessage().contains("continuation frame received without"));
        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, channel.goAwayStatus);
        assertNull(parser.getParser());
    }

    @Test
    public void handleContinuationFrameWithMismatchedStreamIdSendsGoAwayAndThrows() throws IOException {
        Http2FrameHeaderParser headersParser = new Http2FrameHeaderParser(channel, null);
        headersParser.handle(frame(0, Http2Channel.FRAME_TYPE_HEADERS, 0, 1, new byte[0]));
        Http2HeadersParser continuation = headersParser.getContinuationParser();
        assertNotNull(continuation);

        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, continuation);

        IOException exception = assertThrows(IOException.class,
                () -> parser.handle(frame(0, Http2Channel.FRAME_TYPE_CONTINUATION, END_HEADERS, 3, new byte[0])));

        assertEquals(IOException.class, exception.getClass());
        assertTrue(exception.getMessage().contains("continuation frame received without"));
        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, channel.goAwayStatus);
    }

    // ---------------------------------------------------------------------------------------------
    // PUSH_PROMISE
    // ---------------------------------------------------------------------------------------------

    @Test
    public void handlePushPromiseFrameWithEndHeadersFlagReturnsTrue() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(4, Http2Channel.FRAME_TYPE_PUSH_PROMISE, END_HEADERS, 1, new byte[]{0, 0, 0, 2})));

        Http2PushPromiseParser pushPromiseParser = assertInstanceOf(Http2PushPromiseParser.class, parser.getParser());
        assertEquals(2, pushPromiseParser.getPromisedStreamId());
        assertNull(parser.getContinuationParser());
