        assertTrue(parser.handle(frame(4, Http2Channel.FRAME_TYPE_RST_STREAM, 0, 5, new byte[]{0, 0, 0, 8})));

        Http2RstStreamParser rstStreamParser = assertInstanceOf(Http2RstStreamParser.class, parser.getParser());
        assertEquals(8, rstStreamParser.getErrorCode());
