        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, exception.getCode());
        assertTrue(exception.getMessage().contains("stream id must be zero"));
        assertNull(parser.getParser());
    }

    @Test
    public void handleGoAwayFrameParsesLastGoodStreamAndStatusCode() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(8, Http2Channel.FRAME_TYPE_GOAWAY, 0, 0,
                new byte[]{0, 0, 0, 4, 0, 0, 0, 9})));

        Http2GoAwayParser goAwayParser = assertInstanceOf(Http2GoAwayParser.class, parser.getParser());
        assertEquals(4, goAwayParser.getLastGoodStreamId());
