    // ---------------------------------------------------------------------------------------------

    @Test
    public void handlePingFrameWithInvalidLengthThrowsFrameSizeError() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
