    private static ByteBuffer frame(int length, int type, int flags, int streamId, byte[] payload) {
        ByteBuffer buffer = ByteBuffer.allocate(9 + payload.length);
        buffer.put((byte) ((length >> 16) & 0xff));
        buffer.put((byte) ((length >> 8) & 0xff));
        buffer.put((byte) (length & 0xff));
        buffer.put((byte) type);
        buffer.put((byte) flags);
        buffer.put((byte) ((streamId >> 24) & 0xff));
        buffer.put((byte) ((streamId >> 16) & 0xff));
        buffer.put((byte) ((streamId >> 8) & 0xff));
        buffer.put((byte) (streamId & 0xff));
        buffer.put(payload);
        buffer.flip();
        return buffer;
    }

    /**
     * {@link Http2Channel} that only records the goaway codes it is asked to send.
     */
    private static final class RecordingHttp2Channel extends Http2Channel {

        private int goAwayStatus = -1;

        RecordingHttp2Channel(StreamConnection connection) {
            super(connection, null, new DefaultByteBufferPool(false, 1024), null, false, false, true, OptionMap.EMPTY);
        }

        @Override
        public void sendGoAway(int status) {
            this.goAwayStatus = status;
        }
    }

    /**
     * Minimal in-memory {@link StreamConnection}; the parsers tested here never read from or write to it.
     */
    private static final class FakeStreamConnection extends StreamConnection {

        FakeStreamConnection(XnioIoThread thread) {
            super(thread);
            setSourceConduit(new EmptyStreamSourceConduit(thread));
            setSinkConduit(new NullStreamSinkConduit(thread));
        }

        @Override
        public SocketAddress getPeerAddress() {
            return null;
        }

        @Override
        public SocketAddress getLocalAddress() {
            return null;
        }

        @Override
        protected void notifyWriteClosed() {
        }

        @Override
        protected void notifyReadClosed() {
        }
    }
