    @Test
    public void handleIncompleteHeaderReturnsFalseAndKeepsReadState() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertFalse(parser.handle(ByteBuffer.wrap(new byte[]{0, 0, 0, Http2Channel.FRAME_TYPE_SETTINGS, 0, 0, 0, 0})));
        assertNull(parser.getParser());
        assertEquals(8, parser.read);

        // the last header byte is supplied by the next read
        assertTrue(parser.handle(ByteBuffer.wrap(new byte[]{0})));
        assertEquals(9, parser.read);
        assertInstanceOf(Http2SettingsParser.class, parser.getParser());
