    // PRIORITY
    // ---------------------------------------------------------------------------------------------

    @Test
    public void handlePriorityFrameWithIncorrectLengthThrowsFrameSizeError() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
                () -> parser.handle(frame(4, Http2Channel.FRAME_TYPE_PRIORITY, 0, 1, new byte[4])));

        assertEquals(Http2Channel.ERROR_FRAME_SIZE_ERROR, exception.getCode());
        assertNull(parser.getParser());
    }

    @Test
    public void handlePriorityFrameWithZeroStreamIdThrowsProtocolError() {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        ConnectionErrorException exception = assertThrows(ConnectionErrorException.class,
                () -> parser.handle(frame(5, Http2Channel.FRAME_TYPE_PRIORITY, 0, 0, new byte[5])));

        assertEquals(Http2Channel.ERROR_PROTOCOL_ERROR, exception.getCode());
        assertTrue(exception.getMessage().contains("stream id must not be zero"));
        assertNull(parser.getParser());
    }

    @Test
    public void handlePriorityFrameParsesDependencyWeightAndExclusivity() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(5, Http2Channel.FRAME_TYPE_PRIORITY, 0, 3,
                new byte[]{(byte) 0x80, 0, 0, 1, 15})));

        Http2PriorityParser priorityParser = assertInstanceOf(Http2PriorityParser.class, parser.getParser());
        assertEquals(1, priorityParser.getStreamDependency());
        assertEquals(15, priorityParser.getWeight());
        assertTrue(priorityParser.isExclusive());
    }

    // ---------------------------------------------------------------------------------------------
    // unknown frame types / repetition
    // ---------------------------------------------------------------------------------------------

    @Test
    public void handleUnknownFrameTypeDiscardsPayload() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);
        ByteBuffer buffer = frame(3, 0x0a, 0, 0, new byte[]{1, 2, 3});

        assertTrue(parser.handle(buffer));

        Http2DiscardParser discardParser = assertInstanceOf(Http2DiscardParser.class, parser.getParser());
        assertEquals(0, discardParser.remaining);
        assertEquals(0, buffer.remaining());
        assertEquals(0, parser.getFrameLength());
    }

    @Test
    public void handleCalledTwiceReusesTheSameFrameParser() throws IOException {
        Http2FrameHeaderParser parser = new Http2FrameHeaderParser(channel, null);

        assertTrue(parser.handle(frame(3, Http2Channel.FRAME_TYPE_DATA, END_STREAM, 5, new byte[]{1, 2, 3})));
        Http2PushBackParser frameParser = parser.getParser();
        assertNotNull(frameParser);

        assertTrue(parser.handle(ByteBuffer.allocate(0)));
        assertSame(frameParser, parser.getParser(), "the header must not be parsed a second time");
    }

