import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.ValueSource;

class HostHeaderHandlerHandleRequestTests {

    private AtomicInteger nextInvocations;
    private HostHeaderHandler handler;

    @BeforeEach
    void setUp() {
        nextInvocations = new AtomicInteger();
        handler = new HostHeaderHandler(exchange -> nextInvocations.incrementAndGet());
    }

