    void http09WithoutHostHeaderDelegatesToNextHandler() throws Exception {
        assertAccepted(exchange(Protocols.HTTP_0_9));
    }

    @Test
    void http10WithoutHostHeaderDelegatesToNextHandler() throws Exception {
        assertAccepted(exchange(Protocols.HTTP_1_0));
    }

