    void http10WithMultipleHostHeadersIsRejected() throws Exception {
        assertRejected(exchange(Protocols.HTTP_1_0, "one.example", "two.example"),
                HostHeaderHandler.STATUS_TOO_MANY_HOST_HEADERS);
    }

    @Test
    void http10WithMalformedHostHeaderIsRejected() throws Exception {
        assertRejected(exchange(Protocols.HTTP_1_0, "example.com:not-a-port"),
                HostHeaderHandler.STATUS_MALFORMED_PORT);
    }

    @Test
    void http11WithoutHostHeaderIsRejected() throws Exception {
        assertRejected(exchange(Protocols.HTTP_1_1), HostHeaderHandler.STATUS_NO_HOST_HEADER);
    }

    @Test
    void multipleHostHeadersAreRejected() throws Exception {
        assertRejected(exchange(Protocols.HTTP_1_1, "first.example", "second.example"),
                HostHeaderHandler.STATUS_TOO_MANY_HOST_HEADERS);
    }

    @Test
    void threeHostHeadersAreRejected() throws Exception {
        assertRejected(exchange(Protocols.HTTP_1_1, "first.example", "second.example", "third.example"),
                HostHeaderHandler.STATUS_TOO_MANY_HOST_HEADERS);
    }

    @ParameterizedTest(name = "accepts valid Host value [{0}]")
    @ValueSource(strings = {
            "example.com",
            "localhost",
            "sub-domain.example",
            "a_b~c!$&'()*+,;=.",
            "127.0.0.1",
            "255.255.255.255",
            "example%20com",
            "ex%2Fample",
            "[::1]",
            "[2001:db8::1]",
            "[::ffff:192.0.2.128]",
            "[v1.a]",
            "[vF.foo:bar]",
            "[v1.a]:443",
            "example.com:1",
            "example.com:65535",
            "[::1]:443"
    })
    void acceptsValidHostHeader(String hostHeader) throws Exception {
        assertAccepted(exchange(Protocols.HTTP_1_1, hostHeader));
    }

    @ParameterizedTest(name = "rejects malformed Host value [{0}] as {1}")
    @MethodSource("malformedHostCases")
    void rejectsMalformedHostHeader(String hostHeader, String expectedReason) throws Exception {
        assertRejected(exchange(Protocols.HTTP_1_1, hostHeader), expectedReason);
    }

    static Stream<Arguments> malformedHostCases() {
        return Stream.of(
                arguments("example.com:0", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("example.com:65536", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("example.com:-1", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("example.com:abc", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("example.com:", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("[::1]:0", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("[v1.a]:65536", HostHeaderHandler.STATUS_MALFORMED_PORT),
                arguments("[::1", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("foo[::1]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("foo]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[abc]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[::zz]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[v1]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[v1.]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[v.a]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("[vG.a]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("[v1.a b]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("[v1.a/b]", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("bad host", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("user@example.com", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("foo/bar", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("::1", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("foo%2", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("foo%", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL),
                arguments("foo%zz", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS),
                arguments("foo%2G", HostHeaderHandler.STATUS_MALFORMED_IP_LITERAL_BAD_CHARS)
        );
    }

    @Test
    void acceptsHostContainedInAbsoluteRequestUri() throws Exception {
        HttpServerExchange exchange = exchange(Protocols.HTTP_1_1, "example.com");
        exchange.setRequestURI("http://example.com/path", true);

        assertAccepted(exchange);
    }

    @Test
    void acceptsHostWithPortContainedInAbsoluteRequestUri() throws Exception {
        HttpServerExchange exchange = exchange(Protocols.HTTP_1_1, "example.com:8080");
        exchange.setRequestURI("http://example.com:8080/path", true);

        assertAccepted(exchange);
    }

    @Test
    void acceptsIpv6HostContainedInAbsoluteRequestUri() throws Exception {
        HttpServerExchange exchange = exchange(Protocols.HTTP_1_1, "[::1]:8080");
        exchange.setRequestURI("http://[::1]:8080/path", true);

        assertAccepted(exchange);
    }

    @Test
    void rejectsHostNotContainedInAbsoluteRequestUri() throws Exception {
        HttpServerExchange exchange = exchange(Protocols.HTTP_1_1, "example.com");
        exchange.setRequestURI("http://other.example/path", true);

        assertRejected(exchange, HostHeaderHandler.STATUS_HOST_NO_MATCH);
    }

    @Test
    void rejectsEmptyHostPortionWhenRequestUriContainsAuthority() throws Exception {
        HttpServerExchange exchange = exchange(Protocols.HTTP_1_1, ":80");
        exchange.setRequestURI("http://example.com/path", true);

        assertRejected(exchange, HostHeaderHandler.STATUS_HOST_NO_MATCH);
    }

    @Test
    void doesNotCompareHostToUriWhenRequestUriContainsOnlyPath() throws Exception {
        HttpServerExchange exchange = exchange(Protocols.HTTP_1_1, "example.com");
        exchange.setRequestURI("/path", false);

        assertAccepted(exchange);
    }

    private HttpServerExchange exchange(io.undertow.util.HttpString protocol, String... hostHeaders) {
        HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.setProtocol(protocol);
        exchange.setRequestMethod(Methods.GET);
        exchange.setRequestURI("/");
        for (String hostHeader : hostHeaders) {
            exchange.getRequestHeaders().add(Headers.HOST, hostHeader);
        }

        // Completing the exchange up front keeps termination observable without requiring a real connection.
        exchange.addExchangeCompleteListener((completedExchange, nextListener) -> {
        });
        Connectors.terminateRequest(exchange);
        Connectors.terminateResponse(exchange);
        return exchange;
    }

    private void assertAccepted(HttpServerExchange exchange) throws Exception {
        handler.handleRequest(exchange);

        assertEquals(1, nextInvocations.get(), "next handler should be invoked exactly once");
        assertEquals(StatusCodes.OK, exchange.getStatusCode(), "accepted request should retain the default status");
        assertNull(exchange.getReasonPhrase(), "accepted request should not set an error reason phrase");
    }

    private void assertRejected(HttpServerExchange exchange, String expectedReason) throws Exception {
        handler.handleRequest(exchange);

        assertEquals(0, nextInvocations.get(), "next handler must not be invoked for a rejected request");
        assertEquals(StatusCodes.BAD_REQUEST, exchange.getStatusCode());
        assertEquals(expectedReason, exchange.getReasonPhrase());
        assertEquals("0", exchange.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH));
        assertEquals(Headers.CLOSE.toString(), exchange.getResponseHeaders().getFirst(Headers.CONNECTION));
    }
}
