    private static final class RecordingHandler implements HttpHandler {
        private final boolean captureBody;
        private final ScriptedSourceConduit conduit;
        int invocations;
        int readCallsAtNext = -1;
        HttpServerExchange exchange;
        byte[] body = new byte[0];

        private RecordingHandler(boolean captureBody, ScriptedSourceConduit conduit) {
            this.captureBody = captureBody;
            this.conduit = conduit;
        }

        @Override
        public void handleRequest(HttpServerExchange exchange) throws Exception {
            invocations++;
            this.exchange = exchange;
            readCallsAtNext = conduit.readCalls;
            if (!captureBody) {
                return;
            }
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            StreamSourceChannel channel = exchange.getRequestChannel();
            ByteBuffer buffer = ByteBuffer.allocate(64);
            while (true) {
                buffer.clear();
                long read = channel.read(new ByteBuffer[]{buffer}, 0, 1);
                if (read == -1 || read == 0) {
                    break;
                }
                buffer.flip();
                byte[] chunk = new byte[buffer.remaining()];
                buffer.get(chunk);
                out.write(chunk, 0, chunk.length);
            }
            body = out.toByteArray();
        }
    }

