    private static final class ScriptedSourceConduit implements StreamSourceConduit {
        private final Deque<Object> actions = new ArrayDeque<>();
        ReadReadyHandler readReadyHandler;
        int readCalls;
        int resumeReadsCalls;
        int suspendReadsCalls;
        private boolean readShutdown;

        void enqueueBytes(String value) {
            actions.add(bytes(value));
        }

        void enqueueReadResult(int result) {
            actions.add(result);
        }

        void enqueueFailure(IOException failure) {
            actions.add(failure);
        }

        void fireReadReady() {
            ReadReadyHandler handler = readReadyHandler;
            assertNotNull(handler, "a read-ready handler must have been registered");
            handler.readReady();
        }

        @Override
        public int read(ByteBuffer dst) throws IOException {
            readCalls++;
            Object action = actions.poll();
            if (action == null) {
                return -1;
            }
            if (action instanceof Integer) {
                return (Integer) action;
            }
            if (action instanceof IOException) {
                throw (IOException) action;
            }
            byte[] data = (byte[]) action;
            int copied = Math.min(dst.remaining(), data.length);
            dst.put(data, 0, copied);
            if (copied < data.length) {
                actions.addFirst(Arrays.copyOfRange(data, copied, data.length));
            }
            return copied;
        }

        @Override
        public long read(ByteBuffer[] dsts, int offs, int len) throws IOException {
            if (len == 0 || offs >= dsts.length) {
                return 0;
            }
            return read(dsts[offs]);
        }

        @Override
        public long read(ByteBuffer[] dsts) throws IOException {
            return read(dsts, 0, dsts.length);
        }

        @Override
        public long transferTo(long position, long count, java.nio.channels.FileChannel target) {
            return -1;
        }

        @Override
        public long transferTo(long count, ByteBuffer throughBuffer, StreamSinkChannel target) {
            return -1;
        }

        @Override
        public void terminateReads() {
            readShutdown = true;
        }

        @Override
        public boolean isReadShutdown() {
            return readShutdown;
        }

        @Override
        public void resumeReads() {
