package io.undertow.server.handlers.builder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;

import io.undertow.server.handlers.builder.PredicatedHandlersParser.Token;
import org.junit.jupiter.api.Test;

/**
 * Tests for {@link PredicatedHandlersParser#tokenize(String)}.
 *
 * <p>Every token is asserted on both of its observable properties: the token text and the
 * position recorded for it. The position is always the index of the character that terminated
 * the token (a delimiter, a quote, or the end of the input for the very last token).</p>
 */
public class PredicatedHandlersParserTokenizeTests {

    private static final String NEWLINE = "\n";

    private static List<String> render(final Deque<Token> tokens) {
        final List<String> result = new ArrayList<>(tokens.size());
        for (final Token token : tokens) {
            result.add(describe(token));
        }
        return result;
    }

    private static String describe(final Token token) {
        return token.getToken() + "@" + token.getPosition();
    }

    private static String escape(final String value) {
        return value.replace("\r", "\\r").replace("\n", "\\n").replace("\t", "\\t");
    }

    /**
     * Asserts that tokenizing the given input yields exactly the expected tokens, in order, where
     * each expectation is expressed as {@code text@position}.
     */
    private static void assertTokens(final String input, final String... expected) {
        final Deque<Token> tokens = PredicatedHandlersParser.tokenize(input);
        final List<String> actual = render(tokens);
        assertEquals(Arrays.asList(expected), actual,
                "Unexpected token stream for input [" + escape(input) + "]");
    }

    @Test
    public void emptyInputProducesNoTokens() {
        final Deque<Token> tokens = PredicatedHandlersParser.tokenize("");
        assertTrue(tokens.isEmpty());
        assertEquals(0, tokens.size());
    }

    @Test
    public void blankInputProducesNoTokens() {
        // whitespace is a separator, it never produces a token of its own
        assertTokens("   \t  ", new String[0]);
    }

    @Test
    public void singleTokenIsFlushedAtEndOfInput() {
        assertTokens("foo", "foo@3");
    }

    @Test
    public void trailingTextAfterWhitespaceIsFlushedAtEndOfInput() {
        assertTokens("  foo  ", "foo@5");
    }

    @Test
    public void tokensAreSplitOnSpaces() {
        assertTokens("foo bar", "foo@3", "bar@7");
    }

    @Test
    public void tokensAreSplitOnTabs() {
        assertTokens("a\tb", "a@1", "b@3");
    }

    @Test
    public void newlineTerminatesTokenAndProducesNewlineToken() {
        assertTokens("foo\nbar", "foo@3", NEWLINE + "@3", "bar@7");
    }

    @Test
    public void consecutiveNewlinesProduceOneTokenEach() {
        assertTokens("foo\n\nbar", "foo@3", NEWLINE + "@3", NEWLINE + "@4", "bar@8");
        assertTokens("\n\n", NEWLINE + "@0", NEWLINE + "@1");
    }

    @Test
    public void carriageReturnIsTreatedAsNewline() {
        assertTokens("a\rb", "a@1", NEWLINE + "@1", "b@3");
    }

    @Test
    public void carriageReturnLineFeedProducesTwoNewlineTokens() {
        assertTokens("foo\r\nbar", "foo@3", NEWLINE + "@3", NEWLINE + "@4", "bar@8");
    }

    @Test
    public void commentAtStartOfInputIsSkippedTogetherWithItsNewline() {
        assertTokens("#comment\nfoo", "foo@12");
    }

    @Test
    public void commentOnlyInputProducesNoTokens() {
        assertTokens("#c", new String[0]);
        assertTokens("#", new String[0]);
    }

    @Test
    public void commentAtStartOfLineAfterNewlineIsSkipped() {
        assertTokens("foo\n#bar\nbaz", "foo@3", NEWLINE + "@3", "baz@12");
    }

    @Test
    public void quoteInsideCommentIsNotInterpreted() {
        assertTokens("#c\n'x'", "x@5");
    }

    @Test
    public void hashAfterATokenIsNotAComment() {
        // '#' only starts a comment when it is the first token of a line
        assertTokens("foo #bar", "foo@3", "#bar@8");
    }

    @Test
    public void structuralCharactersBecomeTheirOwnTokens() {
        assertTokens("a(b)", "a@1", "(@1", "b@3", ")@3");
        assertTokens("a,b", "a@1", ",@1", "b@3");
        assertTokens("a;b=c", "a@1", ";@1", "b@3", "=@3", "c@5");
        assertTokens("[a]", "[@0", "a@2", "]@2");
    }

    @Test
    public void newlinesInsideBracesAreSuppressed() {
        // the pending text is not flushed by the suppressed newline, so "a" and "b" merge
        assertTokens("{a\nb}", "{@0", "ab@4", "}@4");
    }

    @Test
    public void newlineIsEmittedAgainOnceBracesAreBalanced() {
        assertTokens("(a\nb)\nc", "(@0", "ab@4", ")@4", NEWLINE + "@5", "c@7");
    }

    @Test
    public void newlineIsEmittedAfterUnbalancedClosingBrace() {
        assertTokens("}\nfoo", "}@0", NEWLINE + "@1", "foo@5");
    }

    @Test
    public void spacesInsideBracesStillSeparateTokens() {
        assertTokens("{a b}", "{@0", "a@2", "b@4", "}@4");
    }

    @Test
    public void doubleQuotedStringYieldsTheUnquotedContent() {
        assertTokens("\"foo\"", "foo@4");
    }

    @Test
    public void singleQuotedStringYieldsTheUnquotedContent() {
        assertTokens("'x'", "x@2");
    }

    @Test
    public void quotedStringMayContainWhitespace() {
        assertTokens("a 'b c' d", "a@1", "b c@6", "d@9");
    }

    @Test
    public void adjacentQuotedStringsYieldSeparateTokens() {
        assertTokens("\"a b\" \"c\"", "a b@4", "c@8");
    }

    @Test
    public void escapedDelimiterInsideStringIsUnescaped() {
        assertTokens("\"fo\\\"o\"", "fo\"o@6");
    }

    @Test
    public void singleQuotedStringMayContainDoubleQuotes() {
        assertTokens("'say \"hi\"'", "say \"hi\"@10");
    }

    @Test
    public void unterminatedStringYieldsThePendingContent() {
        assertTokens("\"foo", "foo@4");
    }

    @Test
    public void newlineTerminatesAnUnterminatedString() {
        assertTokens("\"foo\nbar", "foo@4", NEWLINE + "@4", "bar@8");
    }

    @Test
    public void quoteDirectlyAfterContentIsRejected() {
        final IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.tokenize("foo\"bar\""));
        assertTrue(ex.getMessage().contains("Unexpected token"), "unexpected message: " + ex.getMessage());
        assertTrue(ex.getMessage().contains("foo\"bar\""), "unexpected message: " + ex.getMessage());
    }

    @Test
    public void quoteDirectlyAfterContentOnLaterLineIsRejected() {
        final IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.tokenize("a\nfoo\""));
        assertTrue(ex.getMessage().contains("Unexpected token"), "unexpected message: " + ex.getMessage());
    }

    @Test
    public void closingQuoteAfterLineBreakIsRejected() {
        // the unterminated string was closed by the newline, so the final quote follows content
        assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.tokenize("\"foo\nbar\""));
    }

    @Test
    public void arrowIsASingleToken() {
        assertTokens("a -> b", "a@1", "->@3", "b@6");
    }

    @Test
    public void arrowWithoutSurroundingSpacesIsDetected() {
        // the token preceding the arrow is flushed with the position of '>'
        assertTokens("a->b", "a@2", "->@2", "b@4");
    }

    @Test
    public void arrowOnlyInput() {
        assertTokens("->", "->@1");
        assertTokens("  ->  ", "->@3");
    }

    @Test
    public void dashThatDoesNotStartAnArrowIsPartOfTheToken() {
        assertTokens("a-b", "a-b@3");
        assertTokens("header(Content-Type)", "header@6", "(@6", "Content-Type@19", ")@19");
    }

    @Test
    public void dashAtEndOfInputThrows() {
        assertThrows(StringIndexOutOfBoundsException.class, () -> PredicatedHandlersParser.tokenize("a-"));
    }

    @Test
    public void percentOrDollarAtEndOfInputThrows() {
        assertThrows(StringIndexOutOfBoundsException.class, () -> PredicatedHandlersParser.tokenize("abc%"));
        assertThrows(StringIndexOutOfBoundsException.class, () -> PredicatedHandlersParser.tokenize("abc$"));
    }

    @Test
    public void dollarVariableIsKeptAsOneToken() {
        assertTokens("${foo}", "${foo}@6");
    }

    @Test
    public void percentVariableIsKeptAsOneToken() {
        assertTokens("%{foo}", "%{foo}@6");
    }

    @Test
    public void variableMayContainBrackets() {
        assertTokens("${a[0]}", "${a[0]}@7");
    }

    @Test
    public void adjacentVariablesMergeIntoSingleToken() {
        assertTokens("${a}${b}", "${a}${b}@8");
        assertTokens("$%{a}", "$%{a}@5");
    }

    @Test
    public void variableFollowedByNewlineEmitsBothTokens() {
        assertTokens("${a}\n", "${a}@4", NEWLINE + "@4");
    }

    @Test
    public void dollarThatDoesNotStartAVariableIsLiteral() {
        assertTokens("a$b", "a$b@3");
    }

    @Test
    public void percentThatDoesNotStartAVariableIsLiteral() {
        // '%' is followed by a space, so it is just a regular character followed by a separator
        assertTokens("a % b", "a@1", "%@3", "b@5");
    }

    @Test
    public void variablesAndOperatorsCanBeCombined() {
        assertTokens("%{a} and ${b}", "%{a}@4", "and@8", "${b}@13", new String[0].length == 0 ? null : null);
    }

    @Test
    public void fullHandlerExpressionIsTokenized() {
        assertTokens("path(/foo) -> rewrite(/bar)",
                "path@4", "(@4", "/foo@9", ")@9", "->@12",
                "rewrite@21", "(@21", "/bar@26", ")@26");
    }

    @Test
    public void multiLineHandlerConfigurationIsTokenized() {
        assertTokens("path(/a)\n -> rewrite(/b)\n",
                "path@4", "(@4", "/a@7", ")@7", NEWLINE + "@8", "->@11",
                "rewrite@20", "(@20", "/b@23", ")@23", NEWLINE + "@24");
    }

    @Test
    public void resultIsAnOrderedDeque() {
        final Deque<Token> tokens = PredicatedHandlersParser.tokenize("first second third");
        assertEquals(3, tokens.size());
        assertEquals("first@5", describe(tokens.peekFirst()));
        assertEquals("third@18", describe(tokens.peekLast()));
        assertEquals(Arrays.asList("first@5", "second@12", "third@18"), render(tokens));
    }

    @Test
    public void tokenizeIsRepeatable() {
        final String input = "path(/a) -> rewrite(/b)";
        final List<String> first = render(PredicatedHandlersParser.tokenize(input));
        final List<String> second = render(PredicatedHandlersParser.tokenize(input));
        assertEquals(first, second);
        assertFalse(first.isEmpty());
    }
}
