private static final class RequestBuilder {
    private final ByteArrayOutputStream out = new ByteArrayOutputStream();

    RequestBuilder raw(int... values) {
        for (int v : values) out.write(v);
        return this;
    }
    RequestBuilder int16(int v) { out.write((v >> 8) & 0xFF); out.write(v & 0xFF); return this; }
    RequestBuilder string(String s) { return stringBytes(s.getBytes(StandardCharsets.ISO_8859_1)); }
    RequestBuilder stringBytes(byte[] b) { int16(b.length); out.write(b,0,b.length); out.write(0); return this; }
    RequestBuilder nullString() { return int16(0xFFFF); }
    RequestBuilder codedHeader(int code) { return raw(0xA0, code); }
    RequestBuilder header(String name, String value) { return string(name).string(value); }
    RequestBuilder attr(int code, String value) { return raw(code).string(value); }
    RequestBuilder namedAttr(String name, String value) { return raw(0x0A).string(name).string(value); }
    RequestBuilder intAttr(int code, int value) { return raw(code).int16(value); }
    RequestBuilder endAttributes() { return raw(0xFF); }
    byte[] build() { return out.toByteArray(); }
}
