    @Test
    public void parseRequestWithUnencodedUriCharactersThrowsWhenNotAllowed() {
        byte[] data = standardRequest()
                .stringBytes(new byte[] { '/', 'c', 'a', 'f', (byte) 0xC3, (byte) 0xA9 })
                .endAttributes()
                .build();

        assertThrows(BadRequestException.class, () -> parseInOneGo(parser(true, 100, 100, false), data));
    }

    @Test
    public void parseRequestWithUnencodedUriCharactersIsAcceptedWhenAllowed() throws Exception {
        byte[] data = standardRequest()
                .stringBytes(new byte[] { '/', 'c', 'a', 'f', (byte) 0xC3, (byte) 0xA9 })
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parser(true, 100, 100, true), data);

        assertEquals("/caf\u00e9", exchange.getRequestURI());
        assertEquals("/caf\u00e9", exchange.getRequestPath());
        assertEquals("/caf\u00e9", exchange.getRelativePath());
    }

    @Test
