    @Test
    public void parseRequestWithQueryStringAttributeSetsQueryStringAndParameters() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .attribute(5, "foo=1&bar=2")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

        assertTrue(state.isComplete());
        assertFalse(state.badRequest);
        assertEquals("foo=1&bar=2", exchange.getQueryString());
        assertEquals("1", firstParam(exchange.getQueryParameters(), "foo"));
        assertEquals("2", firstParam(exchange.getQueryParameters(), "bar"));
        assertNull(state.currentAttribute);
    }

    @Test
    public void parseRequestWithEncodedQueryStringAttributeDecodesParameters() throws Exception {
        byte[] data = standardRequest()
                .attribute(5, "a=b%26c")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data);

        assertEquals("a=b%26c", exchange.getQueryString());
        assertEquals("b&c", firstParam(exchange.getQueryParameters(), "a"));
    }

    @Test
    public void parseRequestWithUnescapedQueryStringCharactersDecodesThem() throws Exception {
        byte[] data = standardRequest()
                .stringBytes(queryValueWithHighBytes())
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parser(true, 100, 100, true), data);

        assertEquals("q=\u00e9", exchange.getDecodedQueryString());
        assertEquals("\u00e9", firstParam(exchange.getQueryParameters(), "q"));
    }

    private static byte[] queryValueWithHighBytes() {
        // attribute code for QUERY_STRING followed by "q=" + UTF-8 encoded 'é' as raw bytes
        return new byte[] { 0x05, 0x00, 0x04, 'q', '=', (byte) 0xC3, (byte) 0xA9, 0x00 };
    }

