    @Test
    public void parseStopsAtEndOfAttributesAndCompletesOnTerminator() throws Exception {
        byte[] data = standardRequest()
                .attribute(1, "/ctx")
                .build();

        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = new HttpServerExchange(null);
        AjpRequestParser parser = defaultParser();

        parser.parse(ByteBuffer.wrap(data), state, exchange);

        assertFalse(state.isComplete());
        assertEquals(AjpRequestParseState.READING_ATTRIBUTES, state.state);
        assertNotNull(state.attributes);
        assertEquals("/ctx", state.attributes.get(AjpRequestParser.CONTEXT));

