        assertEquals(Methods.PATCH, exchange.getRequestMethod());
    }

    @Test
    public void parseRequestWithSslAttributesPopulatesState() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .attribute(7, "cert-data")
                .attribute(8, "TLS_AES_128_GCM_SHA256")
                .attribute(9, "session-id")
                .intAttribute(11, 256)
                .namedAttribute(AjpRequestParser.AJP_SSL_PROTOCOL, "TLSv1.3")
                .namedAttribute(AjpRequestParser.AJP_REMOTE_PORT, "43210")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

        assertTrue(state.isComplete());
        assertFalse(state.badRequest);
        assertEquals("cert-data", state.sslCert);
        assertEquals("TLS_AES_128_GCM_SHA256", state.sslCipher);
        assertEquals("session-id", state.sslSessionId);
        assertEquals("256", state.sslKeySize);
        assertEquals("TLSv1.3", state.secureProtocol);
        assertEquals(43210, state.remotePort);
        assertEquals("/index.html", exchange.getRequestURI());
    }

    @Test
    public void parseRequestWithKnownAttributesStoresThemInAttributesMap() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .attribute(1, "/my-context")
                .attribute(2, "/servlet")
                .attribute(6, "route-1")
                .attribute(10, "custom-attribute-value")
