        assertEquals("/servlet", attributes.get(AjpRequestParser.SERVLET_PATH));
        assertEquals("route-1", attributes.get(AjpRequestParser.ROUTE));
        assertEquals("custom-attribute-value", attributes.get(AjpRequestParser.REQ_ATTRIBUTE));
    }

    @Test
    public void parseRequestWithCustomAttributeMatchingPatternStoresIt() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .namedAttribute("my.attribute", "some-value")
                .endAttributes()
                .build();

        parseInOneGo(parserWithAllowedAttributes("my\\..*"), data, state);

        assertNotNull(state.attributes);
        assertEquals("some-value", state.attributes.get("my.attribute"));
    }

    @Test
    public void parseRequestWithCustomAttributeNotMatchingPatternIsIgnored() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .namedAttribute("my.attribute", "some-value")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(parserWithAllowedAttributes("other\\..*"), data, state);

        assertTrue(state.isComplete());
        assertNull(state.attributes);
        assertEquals("/index.html", exchange.getRequestURI());
    }

    @Test
    public void parseRequestWithUnknownAttributeCodesIgnoresThem() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .raw(0x00) // unknown (zero) attribute code
                .raw(0x20) // unknown (out of range) attribute code
                .attribute(1, "/ctx")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

        assertTrue(state.isComplete());
        assertFalse(state.badRequest);
        assertNotNull(state.attributes);
        assertEquals(1, state.attributes.size());
        assertEquals("/ctx", state.attributes.get(AjpRequestParser.CONTEXT));
        assertEquals("/index.html", exchange.getRequestURI());
    }

    @Test
    public void parseStopsAtEndOfAttributesAndCompletesOnTerminator() throws Exception {
        byte[] data = standardRequest()
                .attribute(1, "/ctx")
                .build();

        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = new HttpServerExchange(null);
        AjpRequestParser parser = defaultParser();

        parser.parse(ByteBuffer.wrap(data), state, exchange);

        assertFalse(state.isComplete());
        assertEquals(AjpRequestParseState.READING_ATTRIBUTES, state.state);
        assertNotNull(state.attributes);
        assertEquals("/ctx", state.attributes.get(AjpRequestParser.CONTEXT));

        parser.parse(ByteBuffer.wrap(new byte[] { (byte) 0xFF }), state, exchange);

        assertTrue(state.isComplete());
        assertEquals(AjpRequestParseState.DONE, state.state);
        assertNull(state.currentAttribute);
        assertFalse(state.badRequest);
    }
