                .string("HTTP/1.1")
                .stringBytes(new byte[] { '/', 'c', 'a', 'f', (byte) 0xC3, (byte) 0xA9 })
                .string("127.0.0.1")
                .string("")
                .string("localhost")
                .int16(SERVER_PORT)
                .raw(0)
                .int16(0)
                .endAttributes()
