    @Test
    public void parseRequestWithNullQueryStringAttributeYieldsEmptyQueryString() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = standardRequest()
                .raw(5)
                .nullString()
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

