package io.undertow.server.protocol.ajp;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Deque;
import java.util.Map;

import io.undertow.security.impl.ExternalAuthenticationMechanism;
import io.undertow.server.HttpServerExchange;
import io.undertow.util.BadRequestException;
import io.undertow.util.Headers;
import io.undertow.util.HttpString;
import io.undertow.util.Methods;
import io.undertow.util.Protocols;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for {@link AjpRequestParser#parse(ByteBuffer, AjpRequestParseState, HttpServerExchange)}.
 *
 * <p>The tests build raw AJP13 forward requests and drive the parser either with the complete
 * packet in one go, or byte by byte, verifying the resulting parser state and the side effects
 * on the {@link HttpServerExchange}.</p>
 */
public class AjpRequestParserParseTests {

    private static final int FORWARD_REQUEST = 2;
    private static final int SERVER_PORT = 8080;

    // ---------------------------------------------------------------- helpers

    private static AjpRequestParser defaultParser() {
        return new AjpRequestParser("UTF-8", true, 100, 100, false, false);
    }

    private static AjpRequestParser parser(boolean doDecode, int maxParameters, int maxHeaders,
            boolean allowUnescapedCharactersInUrl) {
        return new AjpRequestParser("UTF-8", doDecode, maxParameters, maxHeaders, false, allowUnescapedCharactersInUrl);
    }

    private static AjpRequestParser parserWithAllowedAttributes(String pattern) {
        return new AjpRequestParser("UTF-8", true, 100, 100, false, false, pattern);
    }

    private static HttpServerExchange parseInOneGo(AjpRequestParser parser, byte[] data)
            throws IOException, BadRequestException {
        return parseInOneGo(parser, data, new AjpRequestParseState());
    }

    private static HttpServerExchange parseInOneGo(AjpRequestParser parser, byte[] data, AjpRequestParseState state)
            throws IOException, BadRequestException {
        HttpServerExchange exchange = new HttpServerExchange(null);
        parser.parse(ByteBuffer.wrap(data), state, exchange);
        return exchange;
    }

    private static HttpServerExchange parseByteByByte(AjpRequestParser parser, byte[] data, AjpRequestParseState state)
            throws IOException, BadRequestException {
        HttpServerExchange exchange = new HttpServerExchange(null);
        for (byte b : data) {
            parser.parse(ByteBuffer.wrap(new byte[] { b }), state, exchange);
        }
        return exchange;
    }

    private static String firstParam(Map<String, Deque<String>> params, String name) {
        Deque<String> values = params.get(name);
        assertNotNull(values, "expected parameter '" + name + "' to be present");
        return values.getFirst();
    }

    /** Builds an AJP packet: magic number, data size, prefix code and request method. */
    private static RequestBuilder requestHeader(int method) {
        return new RequestBuilder()
                .int16(0x1234)
                .int16(0)
                .raw(FORWARD_REQUEST)
                .raw(method);
    }

    /** Request head up to (but excluding) the header count. */
    private static RequestBuilder requestHead(String uri, int isSsl) {
        return requestHeader(2)
                .string("HTTP/1.1")
                .string(uri)
                .string("127.0.0.1")
                .string("")
                .string("localhost")
                .int16(SERVER_PORT)
                .raw(isSsl);
    }

    /** A minimal, complete forward request that reads {@code GET /index.html HTTP/1.1}. */
    private static RequestBuilder standardRequest() {
        return requestWithUri("/index.html");
    }

    private static RequestBuilder requestWithUri(String uri) {
        return requestHead(uri, 0).int16(0);
    }

    private static final class RequestBuilder {

        private final ByteArrayOutputStream out = new ByteArrayOutputStream();

        RequestBuilder raw(int... values) {
            for (int value : values) {
                out.write(value);
            }
            return this;
        }

        RequestBuilder int16(int value) {
            out.write((value >> 8) & 0xFF);
            out.write(value & 0xFF);
            return this;
        }

        RequestBuilder string(String value) {
            return stringBytes(value.getBytes(StandardCharsets.ISO_8859_1));
        }

        RequestBuilder stringBytes(byte[] bytes) {
            int16(bytes.length);
            out.write(bytes, 0, bytes.length);
            out.write(0);
            return this;
        }

        RequestBuilder nullString() {
            return int16(0xFFFF);
        }

        /** A header name encoded as a single {@code 0xA0xx} code instead of a string. */
        RequestBuilder codedHeader(int code) {
            return raw(0xA0, code);
        }

        RequestBuilder header(String name, String value) {
            return string(name).string(value);
        }

        RequestBuilder attribute(int code, String value) {
            return raw(code).string(value);
        }

        RequestBuilder namedAttribute(String name, String value) {
            return raw(0x0A).string(name).string(value);
        }

        RequestBuilder intAttribute(int code, int value) {
            return raw(code).int16(value);
        }

        RequestBuilder endAttributes() {
            return raw(0xFF);
        }

        byte[] build() {
            return out.toByteArray();
        }
    }

    // ------------------------------------------------------------- test cases

    @Test
    public void parseWithEmptyBufferDoesNotTouchState() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = new HttpServerExchange(null);
        defaultParser().parse(ByteBuffer.allocate(0), state, exchange);

        assertEquals(AjpRequestParseState.BEGIN, state.state);
        assertFalse(state.isComplete());
        assertEquals(-1, state.currentIntegerPart);
        assertSame(HttpString.EMPTY, exchange.getRequestMethod());
        assertNull(exchange.getRequestURI());
    }

    @Test
    public void parseWithWrongMagicNumberThrowsBadRequest() {
        byte[] data = new RequestBuilder()
                .int16(0x1123)
                .int16(0)
                .raw(FORWARD_REQUEST)
                .build();

        BadRequestException exception = assertThrows(BadRequestException.class,
                () -> parseInOneGo(defaultParser(), data));
        assertTrue(exception.getMessage().contains("Incorrect magic number"),
                "unexpected message: " + exception.getMessage());
    }

    @Test
    public void parseWithPartialMagicNumberWaitsForMoreData() throws Exception {
        AjpRequestParser parser = defaultParser();
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = new HttpServerExchange(null);

        parser.parse(ByteBuffer.wrap(new byte[] { 0x12 }), state, exchange);

        assertFalse(state.isComplete());
        assertEquals(AjpRequestParseState.BEGIN, state.state);
        assertEquals(0x12, state.currentIntegerPart);
        assertNull(exchange.getRequestURI());

        byte[] complete = standardRequest().endAttributes().build();
        byte[] rest = Arrays.copyOfRange(complete, 1, complete.length);
        parser.parse(ByteBuffer.wrap(rest), state, exchange);

        assertTrue(state.isComplete());
        assertEquals(Methods.GET, exchange.getRequestMethod());
        assertEquals("/index.html", exchange.getRequestURI());
    }

    @Test
    public void parseCompleteForwardRequestPopulatesExchangeAndState() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = requestHeader(2)
                .string("HTTP/1.1")
                .string("/foo/bar")
                .string("10.0.0.1")
                .string("client.example.com")
                .string("server.example.com")
                .int16(9090)
                .raw(0)
                .int16(1)
                .codedHeader(0x0B).string("example.com")
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

        assertTrue(state.isComplete());
        assertEquals(2, state.prefix);
        assertEquals(0, state.dataSize);
        assertEquals(1, state.numHeaders);
        assertEquals(1, state.readHeaders);
        assertFalse(state.badRequest);

        assertEquals(Methods.GET, exchange.getRequestMethod());
        assertEquals(Protocols.HTTP_1_1, exchange.getProtocol());
        assertEquals("/foo/bar", exchange.getRequestURI());
        assertEquals("/foo/bar", exchange.getRequestPath());
        assertEquals("/foo/bar", exchange.getRelativePath());
        assertEquals("http", exchange.getRequestScheme());

        assertEquals("10.0.0.1", state.remoteAddress);
        assertEquals("server.example.com", state.serverAddress);
        assertEquals(9090, state.serverPort);
        assertEquals("example.com", exchange.getRequestHeaders().getFirst(Headers.HOST));
        assertNull(state.attributes);
    }

    @Test
    public void parseRequestWithSslFlagSetsHttpsScheme() throws Exception {
        byte[] data = requestHead("/", 1)
                .int16(0)
                .endAttributes()
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data);

        assertEquals("https", exchange.getRequestScheme());
        assertEquals("/", exchange.getRequestURI());
    }

    @Test
    public void parseRequestWithNonForwardPrefixStopsParsing() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        byte[] data = new RequestBuilder()
                .int16(0x1234)
                .int16(0)
                .raw(9) // CPONG, not a forward request
                .raw(2)
                .string("HTTP/1.1")
                .build();

        HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

        assertTrue(state.isComplete());
        assertEquals(9, state.prefix);
        assertSame(HttpString.EMPTY, exchange.getRequestMethod());
