/** Builds an AJP packet: magic number, data size, prefix code and request method. */
private static RequestBuilder requestHeader(int method) {
    return new RequestBuilder()
            .int16(0x1234)
            .int16(0)
            .raw(FORWARD_REQUEST)
            .raw(method);
}

/** Request head up to (but excluding) the header count. */
private static RequestBuilder requestHead(String uri, int isSsl) {
    return requestHead(2, uri, isSsl);
}

/** Request head up to (but excluding) the header count, for an arbitrary request method. */
private static RequestBuilder requestHead(int method, String uri, int isSsl) {
    return requestHeader(method)
            .string("HTTP/1.1")
            .string(uri)
            .string("127.0.0.1")
            .string("")
            .string("localhost")
            .int16(SERVER_PORT)
            .raw(isSsl);
}

/** A minimal, complete forward request with the given method. */
private static RequestBuilder requestWithMethod(int method) {
    return requestHead(method, "/method", 0).int16(0);
}

