/**
 * Unit tests for {@link AjpRequestParser#parse(ByteBuffer, AjpRequestParseState, HttpServerExchange)}.
 *
 * <p>The tests build raw AJP13 forward requests and drive the parser either with the complete
 * packet in one go, or byte by byte, verifying the resulting parser state and the side effects
 * on the {@link HttpServerExchange}.</p>
 */
public class AjpRequestParserParseTests {

    private static final int FORWARD_REQUEST = 2;
    private static final int SERVER_PORT = 8080;

    // ---------------------------------------------------------------- helpers

    private static AjpRequestParser defaultParser() {
        return new AjpRequestParser("UTF-8", true, 100, 100, false, false);
    }

    private static AjpRequestParser parser(boolean doDecode, int maxParameters, int maxHeaders,
            boolean allowUnescapedCharactersInUrl) {
        return new AjpRequestParser("UTF-8", doDecode, maxParameters, maxHeaders, false, allowUnescapedCharactersInUrl);
    }

    private static AjpRequestParser parserWithAllowedAttributes(String pattern) {
        return new AjpRequestParser("UTF-8", true, 100, 100, false, false, pattern);
    }

    private static HttpServerExchange parseInOneGo(AjpRequestParser parser, byte[] data)
            throws IOException, BadRequestException {
        return parseInOneGo(parser, data, new AjpRequestParseState());
    }

    private static HttpServerExchange parseInOneGo(AjpRequestParser parser, byte[] data, AjpRequestParseState state)
            throws IOException, BadRequestException {
        HttpServerExchange exchange = new HttpServerExchange(null);
        parser.parse(ByteBuffer.wrap(data), state, exchange);
        return exchange;
    }

    private static HttpServerExchange parseByteByByte(AjpRequestParser parser, byte[] data, AjpRequestParseState state)
            throws IOException, BadRequestException {
        HttpServerExchange exchange = new HttpServerExchange(null);
        for (byte b : data) {
            parser.parse(ByteBuffer.wrap(new byte[] { b }), state, exchange);
        }
        return exchange;
    }

    private static String firstParam(Map<String, Deque<String>> params, String name) {
        Deque<String> values = params.get(name);
        assertNotNull(values, "expected parameter '" + name + "' to be present");
        return values.getFirst();
    }

    /** Builds an AJP packet: magic number, data size, prefix code and request method. */
    private static RequestBuilder requestHeader(int method) {

    assertFalse(state.isComplete());
    assertEquals(-1, state.currentIntegerPart);
    assertSame(HttpString.EMPTY, exchange.getRequestMethod());
    assertNull(exchange.getRequestURI());
}

