@Test
public void parseWithPartialMagicNumberWaitsForMoreData() throws Exception {
    AjpRequestParser parser = defaultParser();
    AjpRequestParseState state = new AjpRequestParseState();
    HttpServerExchange exchange = new HttpServerExchange(null);

    parser.parse(ByteBuffer.wrap(new byte[] { 0x12 }), state, exchange);

    assertFalse(state.isComplete());
    assertEquals(AjpRequestParseState.BEGIN, state.state);
    assertEquals(0x12, state.currentIntegerPart);
    assertNull(exchange.getRequestURI());

    byte[] complete = standardRequest().endAttributes().build();
    byte[] rest = Arrays.copyOfRange(complete, 1, complete.length);
    parser.parse(ByteBuffer.wrap(rest), state, exchange);

    assertTrue(state.isComplete());
    assertEquals(Methods.GET, exchange.getRequestMethod());
    assertEquals("/index.html", exchange.getRequestURI());
}

@Test
public void parseCompleteForwardRequestPopulatesExchangeAndState() throws Exception {
    AjpRequestParseState state = new AjpRequestParseState();
    byte[] data = requestHeader(2)
            .string("HTTP/1.1")
            .string("/foo/bar")
            .string("10.0.0.1")
            .string("client.example.com")
            .string("server.example.com")
            .int16(9090)
            .raw(0)
            .int16(1)
            .codedHeader(0x0B).string("example.com")
            .endAttributes()
            .build();

    HttpServerExchange exchange = parseInOneGo(defaultParser(), data, state);

    assertTrue(state.isComplete());
    assertEquals(2, state.prefix);
    assertEquals(0, state.dataSize);
    assertEquals(1, state.numHeaders);
    assertFalse(state.badRequest);

    assertEquals(Methods.GET, exchange.getRequestMethod());
    assertEquals(Protocols.HTTP_1_1, exchange.getProtocol());
    assertEquals("/foo/bar", exchange.getRequestURI());
    assertEquals("/foo/bar", exchange.getRequestPath());
    assertEquals("/foo/bar", exchange.getRelativePath());
    assertEquals("http", exchange.getRequestScheme());

    assertEquals("10.0.0.1", state.remoteAddress);
    assertEquals("server.example.com", state.serverAddress);
    assertEquals(9090, state.serverPort);
    assertEquals("example.com", exchange.getRequestHeaders().getFirst(Headers.HOST));
    assertNull(state.attributes);
}

