@Test
public void parseByteByByteProducesTheSameResultAsParsingInOneGo() throws Exception {
    byte[] data = requestHeader(4)
            .string("HTTP/1.1")
            .string("/byte/wise")
            .string("192.168.0.5")
            .string("")
            .string("bytehost")
            .int16(8443)
            .raw(1)
            .int16(1)
            .codedHeader(0x09).string("session=abc")
            .attribute(1, "/context")
            .endAttributes()
            .build();

    AjpRequestParseState incrementalState = new AjpRequestParseState();
    HttpServerExchange incremental = parseByteByByte(defaultParser(), data, incrementalState);
    AjpRequestParseState wholeState = new AjpRequestParseState();
    HttpServerExchange whole = parseInOneGo(defaultParser(), data, wholeState);

    assertTrue(incrementalState.isComplete());
    assertEquals(wholeState.serverPort, incrementalState.serverPort);
    assertEquals(wholeState.remoteAddress, incrementalState.remoteAddress);
    assertEquals(wholeState.attributes, incrementalState.attributes);

    assertEquals(Methods.POST, incremental.getRequestMethod());
    assertEquals(Protocols.HTTP_1_1, incremental.getProtocol());
    assertEquals("/byte/wise", incremental.getRequestURI());
    assertEquals("https", incremental.getRequestScheme());
    assertEquals("session=abc", incremental.getRequestHeaders().getFirst(Headers.COOKIE));
    assertEquals("192.168.0.5", incrementalState.remoteAddress);
    assertEquals(8443, incrementalState.serverPort);
    assertEquals("/context", incrementalState.attributes.get(AjpRequestParser.CONTEXT));

    assertEquals(whole.getRequestMethod(), incremental.getRequestMethod());
    assertEquals(whole.getRequestURI(), incremental.getRequestURI());
    assertEquals(whole.getRequestPath(), incremental.getRequestPath());
    assertEquals("session=abc", whole.getRequestHeaders().getFirst(Headers.COOKIE));
}

