    @Test
    void fragmentedControlFrameIsRejected() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(false, 0, OPCODE_PING), secondByte(false, 0))));

        assertMessageContains(exception, "Fragmented control frame");
        assertFalse(header.isDone());
    }

    @Test
    void controlFrameWithExtendedPayloadLengthIsRejected() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(true, 0, OPCODE_PING), secondByte(false, 126))));

        assertMessageContains(exception, "Control frame with payload length > 125 octets");
        assertFalse(header.isDone());
    }

    @Test
    void controlFrameWithMaximumAllowedPayloadLengthIsAccepted() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_PING), secondByte(false, 125)));

        assertTrue(header.isDone());
        assertEquals(125, header.getFrameLength());
    }

    @Test
    void reservedControlOpcodeIsRejected() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(true, 0, 0xB), secondByte(false, 0))));

        assertMessageContains(exception, "Control frame using reserved opcode = 11");
        assertFalse(header.isDone());
    }

    @Test
    void closeFrameWithPayloadLengthOneIsRejected() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

