    }

    // -------------------------------------------------------------- rsv / extension handling

    @Test
    void reservedBitsAreRejectedWhenExtensionsAreNotSupported() {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        WebSocketFrameCorruptedException exception = assertThrows(WebSocketFrameCorruptedException.class,
                () -> header.handle(buffer(firstByte(true, 0x4, OPCODE_TEXT), secondByte(false, 0))));

        assertMessageContains(exception, "Extensions not allowed but received rsv of 4");
        assertFalse(header.isDone());
    }

    @Test
    void reservedBitsAreAcceptedWhenExtensionsAreSupported() throws Exception {
        WebSocket07Channel channel = newChannel(true, true);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0x4, OPCODE_TEXT), secondByte(false, 7)));

