        assertEquals(7, header.getFrameLength());
    }

    @Test
    void zeroReservedBitsAreAcceptedWithoutExtensions() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0x0, OPCODE_TEXT), secondByte(false, 1)));

