import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link WebSocket07Channel.WebSocketFrameHeader#handle(ByteBuffer)}, the frame header
 * decoder of the WebSocket protocol version 07 channel.
 *
 * <p>The tests drive the state machine with raw frame bytes only, and verify the observable
 * results of parsing: whether the header is complete, the decoded payload length, the fin flag,
 * the masking key, how many bytes were consumed from the buffer and which validation errors are
 * reported for malformed frames.</p>
 */
class WebSocket07ChannelHandleTests {

    private static final byte OPCODE_CONT = 0x0;
    private static final byte OPCODE_TEXT = 0x1;
    private static final byte OPCODE_BINARY = 0x2;
    private static final byte OPCODE_CLOSE = 0x8;
    private static final byte OPCODE_PING = 0x9;
    private static final byte OPCODE_PONG = 0xA;

    // -------------------------------------------------------------- helpers

    /**
     * Builds a buffer out of raw (possibly out of byte range) byte values.
     */
    private static ByteBuffer buffer(int... bytes) {
        byte[] data = new byte[bytes.length];
        for (int i = 0; i < bytes.length; i++) {
            data[i] = (byte) bytes[i];
        }
        return ByteBuffer.wrap(data);
    }

    /**
     * Builds the first header byte: FIN, RSV and opcode.
     */
    private static int firstByte(boolean fin, int rsv, int opcode) {
        int b = opcode & 0x0F;
        b |= (rsv & 0x07) << 4;
        if (fin) {
            b |= 0x80;
        }
        return b;
    }

    /**
     * Builds the second header byte: MASK and PAYLOAD LEN.
     */
    private static int secondByte(boolean masked, int payloadLenOrMarker) {
        int b = payloadLenOrMarker & 0x7F;
        if (masked) {
            b |= 0x80;
        }
        return b;
    }

    private static WebSocket07Channel newChannel(boolean client, boolean allowExtensions) {
        StreamConnection connection = newConnection();
        return new WebSocket07Channel(connection, new TestByteBufferPool(), "ws://localhost/test", null, client,
                allowExtensions, new TestExtensionFunction(), Collections.<WebSocketChannel>emptySet(),
                OptionMap.EMPTY);
    }

    private static WebSocket07Channel.WebSocketFrameHeader newHeader(WebSocket07Channel channel) {
        return channel.new WebSocketFrameHeader();
    }

    private static StreamConnection newConnection() {
        ConduitStreamSourceChannel sourceChannel = new ConduitStreamSourceChannel(Configurable.EMPTY,
                new TestSourceConduit());
        ConduitStreamSinkChannel sinkChannel = new ConduitStreamSinkChannel(Configurable.EMPTY, new TestSinkConduit());
        StreamConnection connection = EasyMock.createNiceMock(StreamConnection.class);
        EasyMock.expect(connection.getSourceChannel()).andStubReturn(sourceChannel);
        EasyMock.expect(connection.getSinkChannel()).andStubReturn(sinkChannel);
        EasyMock.replay(connection);
        return connection;
    }

    private static void assertMessageContains(Throwable throwable, String expected) {
        String message = throwable.getMessage();
        assertTrue(message != null && message.contains(expected),
                "Expected message containing <" + expected + "> but was <" + message + ">");
    }

    // -------------------------------------------------------------- basic state machine tests

    @Test
    void emptyBufferDoesNotCompleteTheHeader() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer empty = buffer();
        header.handle(empty);

        assertFalse(header.isDone(), "an empty buffer must not complete the header");
        assertEquals(0, header.getFrameLength());
        assertEquals(0, empty.remaining(), "an empty buffer must not be consumed");
    }

    @Test
    void emptyBufferWhileWaitingForSecondHeaderByteDoesNotCompleteTheHeader() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_TEXT)));
        assertFalse(header.isDone(), "only the first header byte has been read");

        header.handle(buffer());
        assertFalse(header.isDone(), "still waiting for the second header byte");
        assertEquals(0, header.getFrameLength());
    }

    @Test
    void singleUnmaskedTextFrameWithShortPayload() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 5));
        header.handle(frame);

        assertTrue(header.isDone());
        assertTrue(header.isFinalFragment());
        assertEquals(5, header.getFrameLength());
        assertEquals(0, header.getMaskingKey(), "an unmasked frame has no masking key");
        assertEquals(0, frame.remaining(), "the whole header must be consumed");
    }

    @Test
    void headerSplitOverTwoInvocationsIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY)));
        assertFalse(header.isDone());

        header.handle(buffer(secondByte(false, 42)));
        assertTrue(header.isDone());
        assertTrue(header.isFinalFragment());
        assertEquals(42, header.getFrameLength());
    }

    @Test
    void zeroLengthPayloadIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 0)));

        assertTrue(header.isDone());
        assertEquals(0, header.getFrameLength());
    }

    @Test
    void maximumSevenBitPayloadLengthIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 125)));

        assertTrue(header.isDone());
        assertEquals(125, header.getFrameLength());
    }

    @Test
    void nonFinalFrameIsReportedAsNotFinalFragment() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(false, 0, OPCODE_TEXT), secondByte(false, 3)));

        assertTrue(header.isDone());
        assertFalse(header.isFinalFragment());
        assertEquals(3, header.getFrameLength());
    }

    @Test
    void handleDoesNothingOnceTheHeaderIsComplete() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(false, 7)));
        assertTrue(header.isDone());

        ByteBuffer extra = buffer(firstByte(true, 0, OPCODE_PING), secondByte(false, 0));
        header.handle(extra);

        assertTrue(header.isDone());
        assertEquals(7, header.getFrameLength(), "the length of the completed header must not change");
        assertEquals(0, extra.position(), "no bytes may be consumed for an already completed header");
    }

    @Test
    void onlyTheFirstFrameOfABufferIsParsed() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frames = buffer(
                firstByte(true, 0, OPCODE_TEXT), secondByte(false, 1),
                firstByte(true, 0, OPCODE_PING), secondByte(false, 0));
        header.handle(frames);

        assertTrue(header.isDone());
        assertEquals(1, header.getFrameLength());
        assertEquals(2, frames.position(), "only the first frame header may be consumed");
        assertEquals(2, frames.remaining());
    }

    // -------------------------------------------------------------- extended payload length tests

    @Test
    void sixteenBitExtendedPayloadLengthIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 126), 0x01, 0x00);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(256, header.getFrameLength());
        assertEquals(0, frame.remaining());
    }

    @Test
    void sixteenBitExtendedPayloadLengthIsUnsigned() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 126), 0xFF, 0xFF));

        assertTrue(header.isDone());
        assertEquals(65535, header.getFrameLength(), "the extended length must be treated as unsigned");
    }

    @Test
    void sixtyFourBitExtendedPayloadLengthIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 127),
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(256, header.getFrameLength());
        assertEquals(0, frame.remaining());
    }

    @Test
    void sixtyFourBitExtendedPayloadLengthWithHighBytesIsDecoded() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 127),
                0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08));

        assertTrue(header.isDone());
        assertEquals(0x0102030405060708L, header.getFrameLength());
    }

    @Test
    void incompleteEightByteExtendedPayloadLengthIsPostponed() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer partial = buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 127), 0x01, 0x02);
        header.handle(partial);
        assertFalse(header.isDone(), "the 8 byte extended length is not complete yet");
        assertEquals(0, partial.remaining(), "the available bytes must be consumed");

        ByteBuffer rest = buffer(0x03, 0x04, 0x05, 0x06, 0x07, 0x08);
        header.handle(rest);
        assertTrue(header.isDone());
        assertEquals(0x0102030405060708L, header.getFrameLength());
        assertEquals(0, rest.remaining());
    }

    @Test
    void extendedPayloadLengthMarkerWithoutFollowingBytesIsPostponed() throws Exception {
        WebSocket07Channel channel = newChannel(true, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        header.handle(buffer(firstByte(true, 0, OPCODE_BINARY), secondByte(false, 126)));
        assertFalse(header.isDone(), "the extended 16 bit length has not been read yet");

        header.handle(buffer(0x00, 0x7D));
        assertTrue(header.isDone());
        assertEquals(125, header.getFrameLength());
    }

    // -------------------------------------------------------------- masking tests

    @Test
    void maskedFrameReadsTheMaskingKey() throws Exception {
        WebSocket07Channel channel = newChannel(false, false);
        WebSocket07Channel.WebSocketFrameHeader header = newHeader(channel);

        ByteBuffer frame = buffer(firstByte(true, 0, OPCODE_TEXT), secondByte(true, 3),
                0x0A, 0x0B, 0x0C, 0x0D);
        header.handle(frame);

        assertTrue(header.isDone());
        assertEquals(3, header.getFrameLength());
        assertEquals(0x0A0B0C0D, header.getMaskingKey());
        assertEquals(0, frame.remaining());
    }

    @Test
    void maskedFrameWithExtendedPayloadLengthReadsTheMaskingKey() throws Exception {
        WebSocket07Channel channel = newChannel(false, false);
