        StreamConnection connection = EasyMock.createNiceMock(StreamConnection.class);
        EasyMock.expect(connection.getSourceChannel()).andStubReturn(sourceChannel);
        EasyMock.expect(connection.getSinkChannel()).andStubReturn(sinkChannel);
        EasyMock.replay(connection);
        return connection;
