class RewriteHandlerHandleRequestTests {

    private HttpServerExchange exchange;
    private ServletRequestContext servletRequestContext;
    private HttpServletRequestImpl request;
    private HttpServletResponseImpl response;
    private Deployment deployment;
    private HttpHandler deploymentHandler;
    private HttpHandler next;
    private HeaderMap requestHeaders;

    @BeforeEach
    void setUp() {
        exchange = mock(HttpServerExchange.class);
        servletRequestContext = mock(ServletRequestContext.class);
        request = mock(HttpServletRequestImpl.class);
        response = mock(HttpServletResponseImpl.class);
        deployment = mock(Deployment.class);
        deploymentHandler = mock(HttpHandler.class);
        next = mock(HttpHandler.class);
        requestHeaders = new HeaderMap();

        when(exchange.getAttachment(ServletRequestContext.ATTACHMENT_KEY)).thenReturn(servletRequestContext);
        when(exchange.getRequestHeaders()).thenReturn(requestHeaders);
        when(exchange.getRelativePath()).thenReturn("/old");
        when(exchange.getHostPort()).thenReturn(8080);
        when(servletRequestContext.getOriginalRequest()).thenReturn(request);
        when(servletRequestContext.getOriginalResponse()).thenReturn(response);
        when(servletRequestContext.getDeployment()).thenReturn(deployment);
        when(deployment.getHandler()).thenReturn(deploymentHandler);
        when(request.getServerName()).thenReturn("example.com");
        when(request.getContextPath()).thenReturn("");
    }

    @Test
    void nullRulesDelegateToNextHandler() throws Exception {
        RewriteHandler handler = newHandler(new RewriteConfig(null, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(next).handleRequest(exchange);
        verify(deploymentHandler, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void emptyRulesDelegateToNextHandler() throws Exception {
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[0], Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(next).handleRequest(exchange);
        verify(deploymentHandler, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void alreadyInvokedRequestDelegatesToNextHandlerAndClearsMarker() throws Exception {
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{returning("/new")}, Collections.emptyMap()));
        handler.invoked.set(Boolean.TRUE);

        handler.handleRequest(exchange);

        verify(next).handleRequest(exchange);
        verify(deploymentHandler, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void nonMatchingRuleDelegatesToNextHandler() throws Exception {
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{returning(null)}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(next).handleRequest(exchange);
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(exchange, never()).setRequestURI(anyString());
        assertNull(handler.invoked.get());
    }

    @Test
    void urlRewriteUpdatesExchangeAndReinvokesDeploymentHandler() throws Exception {
        when(request.getContextPath()).thenReturn("/ctx");
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{returning("/new")}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(exchange).setRequestURI("/ctx/new");
        verify(exchange).setRequestPath("/ctx/new");
        verify(exchange).setRelativePath("/new");
        verify(deploymentHandler).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void rewriteWithQueryStringRebuildsUriAndQueryParameters() throws Exception {
        when(request.getContextPath()).thenReturn("/ctx");
        Map<String, Deque<String>> queryParameters = new LinkedHashMap<>();
        queryParameters.put("stale", new java.util.ArrayDeque<>(Collections.singletonList("value")));
        when(exchange.getQueryParameters()).thenReturn(queryParameters);
        ServerConnection connection = mock(ServerConnection.class);
        when(exchange.getConnection()).thenReturn(connection);
        when(connection.getUndertowOptions()).thenReturn(OptionMap.EMPTY);

        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{returning("/new?x=1")}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(exchange).setRequestURI("/ctx/new");
        verify(exchange).setRequestPath("/ctx/new");
        verify(exchange).setRelativePath("/new");
        verify(exchange).setQueryString("x=1");
        assertFalse(queryParameters.containsKey("stale"));
        assertEquals("1", queryParameters.get("x").peekFirst());
        verify(deploymentHandler).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
    }

    @Test
    void hostRewriteUpdatesHostHeaderAndReinvokesDeploymentHandler() throws Exception {
        when(request.getServerName()).thenReturn("old.example.com");
        RewriteRule rule = returning("new.example.com");
        rule.setHost(true);

        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        assertEquals("new.example.com:8080", requestHeaders.getFirst(Headers.HOST));
        verify(exchange).setRequestURI("/old");
        verify(exchange).setRequestPath("/old");
        verify(exchange).setRelativePath("/old");
        verify(deploymentHandler).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
    }

    @Test
    void forbiddenRuleSends403AndStopsProcessing() throws Exception {
        RewriteRule rule = returning("/blocked");
        rule.setForbidden(true);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(response).sendError(HttpServletResponse.SC_FORBIDDEN);
        verify(exchange, never()).setRequestURI(anyString());
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void goneRuleSends410AndStopsProcessing() throws Exception {
        RewriteRule rule = returning("/removed");
        rule.setGone(true);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(response).sendError(HttpServletResponse.SC_GONE);
        verify(exchange, never()).setRequestURI(anyString());
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void redirectRuleAppendsQueryStringAndContextPath() throws Exception {
        when(request.getContextPath()).thenReturn("/app");
        when(request.getQueryString()).thenReturn("a=b&c=d");
        RewriteRule rule = returning("/new");
        rule.setRedirect(true);
        rule.setRedirectCode(HttpServletResponse.SC_MOVED_PERMANENTLY);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(response).sendRedirect("/app/new?a=b&c=d");
        verify(response).setStatus(HttpServletResponse.SC_MOVED_PERMANENTLY);
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
        assertNull(handler.invoked.get());
    }

    @Test
    void redirectRuleLeavesAbsoluteUrlUnchanged() throws Exception {
        when(request.getContextPath()).thenReturn("/app");
        RewriteRule rule = returning("https://example.com/new");
        rule.setRedirect(true);
        rule.setRedirectCode(HttpServletResponse.SC_TEMPORARY_REDIRECT);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(response).sendRedirect("https://example.com/new");
        verify(response).setStatus(HttpServletResponse.SC_TEMPORARY_REDIRECT);
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
    }

    @Test
    void redirectRuleAppendsQueryToUrlThatAlreadyContainsQuestionMarkWhenQsappend() throws Exception {
        when(request.getContextPath()).thenReturn("/app");
        when(request.getQueryString()).thenReturn("a=b");
        RewriteRule rule = returning("/new?");
        rule.setRedirect(true);
        rule.setQsappend(true);
        rule.setRedirectCode(HttpServletResponse.SC_FOUND);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(response).sendRedirect("/app/new?&a=b");
        verify(response).setStatus(HttpServletResponse.SC_FOUND);
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(next, never()).handleRequest(exchange);
    }

    @Test
    void cookieRuleAddsConfiguredCookie() throws Exception {
        RewriteRule rule = returning("/new");
        rule.setCookie(true);
        rule.setCookieName("session");
        rule.cookieResult.set("cookie-value");
        rule.setCookieDomain("example.com");
        rule.setCookieLifetime(3600);
        rule.setCookiePath("/app");
        rule.setCookieSecure(true);
        rule.setCookieHttpOnly(true);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        ArgumentCaptor<Cookie> cookieCaptor = ArgumentCaptor.forClass(Cookie.class);
        verify(response).addCookie(cookieCaptor.capture());
        Cookie cookie = cookieCaptor.getValue();
        assertEquals("session", cookie.getName());
        assertEquals("cookie-value", cookie.getValue());
        assertEquals("example.com", cookie.getDomain());
        assertEquals(3600, cookie.getMaxAge());
        assertEquals("/app", cookie.getPath());
        assertTrue(cookie.getSecure());
        assertTrue(cookie.isHttpOnly());
        verify(deploymentHandler).handleRequest(exchange);
    }

    @Test
    void envRuleStoresRequestAttributeAndExchangeAttachment() throws Exception {
        RewriteRule rule = returning("/new");
        rule.setEnv(true);
        rule.addEnvName("REWRITE_ENV");
        rule.addEnvValue("resolved-value");
        rule.envResult.add(new ThreadLocal<>());
        rule.envResult.get(0).set("resolved-value");
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(request).setAttribute("REWRITE_ENV", "resolved-value");
        @SuppressWarnings("unchecked")
        ArgumentCaptor<Map<String, String>> attributesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(exchange).putAttachment(eq(HttpServerExchange.REQUEST_ATTRIBUTES), attributesCaptor.capture());
        assertEquals("resolved-value", attributesCaptor.getValue().get("REWRITE_ENV"));
        assertEquals(1, attributesCaptor.getValue().size());
        verify(deploymentHandler).handleRequest(exchange);
    }

    @Test
    void typeRuleSetsContentTypeHeader() throws Exception {
        RewriteRule rule = returning("/new");
        rule.setType(true);
        rule.setTypeValue("text/plain");
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        assertEquals("text/plain", requestHeaders.getFirst(Headers.CONTENT_TYPE));
        verify(deploymentHandler).handleRequest(exchange);
    }

    @Test
    void qsappendRuleAppendsOriginalQueryStringToRewrittenUrl() throws Exception {
        Map<String, Deque<String>> queryParameters = new LinkedHashMap<>();
        when(exchange.getQueryParameters()).thenReturn(queryParameters);
        ServerConnection connection = mock(ServerConnection.class);
        when(exchange.getConnection()).thenReturn(connection);
        when(connection.getUndertowOptions()).thenReturn(OptionMap.EMPTY);
        when(request.getQueryString()).thenReturn("a=b");

        RewriteRule rule = returning("/new?");
        rule.setQsappend(true);
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{rule}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(exchange).setRequestPath("/new");
        verify(exchange).setRelativePath("/new");
        verify(exchange).setQueryString("&a=b");
        assertNotNull(queryParameters.get("a"));
        assertEquals("b", queryParameters.get("a").peekFirst());
        verify(deploymentHandler).handleRequest(exchange);
    }

    @Test
    void chainRuleWithNoMatchSkipsFollowingNonChainedRule() throws Exception {
        RewriteRule chained = returning(null);
        chained.setChain(true);
        RewriteRule following = returning("/should-be-skipped");
        RewriteHandler handler = newHandler(new RewriteConfig(new RewriteRule[]{chained, following}, Collections.emptyMap()));

        handler.handleRequest(exchange);

        verify(next).handleRequest(exchange);
        verify(deploymentHandler, never()).handleRequest(exchange);
        verify(exchange, never()).setRequestURI(anyString());
    }

    @Test
    void lastRuleStopsProcessingAndUsesItsRewriteResult() throws Exception {
        RewriteRule lastRule = returning("/first");
        lastRule.setLast(true);
