import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;

/**
 * Tests for {@link Substitution#parse(Map)}.
 */
class SubstitutionParseTests {

    private static Map<String, RewriteMap> noMaps() {
        return Collections.emptyMap();
    }

    private static Substitution parse(String sub) {
        return parse(sub, noMaps());
    }

    private static Substitution parse(String sub, Map<String, RewriteMap> maps) {
        Substitution substitution = new Substitution();
        substitution.setSub(sub);
        substitution.parse(maps);
        return substitution;
    }

    private static RewriteMap lookupMap(final Map<String, String> values) {
        return new RewriteMap() {
            @Override
            public String setParameters(String params) {
                return null;
            }

            @Override
            public String lookup(String key) {
                return values.get(key);
            }
        };
    }

    private static Resolver resolver(final Map<String, String> values) {
        return new Resolver() {
            @Override
            public String resolve(String key) {
                return values.get(key);
            }

            @Override
            public String resolveEnv(String key) {
                return values.get("ENV:" + key);
            }

            @Override
            public String resolveSsl(String key) {
                return values.get("SSL:" + key);
            }

            @Override
            public String resolveHttp(String key) {
                return values.get("HTTP:" + key);
            }

            @Override
            public boolean resolveResource(int type, String name) {
                return false;
            }
        };
    }

    private static Matcher matcher(String regex, String input) {
        return Pattern.compile(regex).matcher(input);
    }

    @Test
    void emptySubstitutionProducesNoElements() {
        Substitution substitution = parse("");

        assertEquals(0, substitution.elements.length);
        assertEquals("", substitution.evaluate(null, null, null));
    }

    @Test
    void parsesStaticTextOnly() {
        Substitution substitution = parse("hello world");

        assertEquals(1, substitution.elements.length);
        Substitution.StaticElement element =
                assertInstanceOf(Substitution.StaticElement.class, substitution.elements[0]);
        assertEquals("hello world", element.value);
        assertEquals("hello world", substitution.evaluate(null, null, null));
    }

    @Test
    void parsesRuleBackReference() {
        Substitution substitution = parse("$3");

        assertEquals(1, substitution.elements.length);
        Substitution.RewriteRuleBackReferenceElement element =
                assertInstanceOf(Substitution.RewriteRuleBackReferenceElement.class, substitution.elements[0]);
        assertEquals(3, element.n);
        assertEquals("c", substitution.evaluate(matcher("(a)(b)(c)", "abc"), null, null));
    }

    @Test
    void parsesStaticTextAroundRuleBackReference() {
        Substitution substitution = parse("before-$2-after");

        assertEquals(3, substitution.elements.length);
        Substitution.StaticElement before =
                assertInstanceOf(Substitution.StaticElement.class, substitution.elements[0]);
        assertEquals("before-", before.value);
        Substitution.RewriteRuleBackReferenceElement reference =
                assertInstanceOf(Substitution.RewriteRuleBackReferenceElement.class, substitution.elements[1]);
        assertEquals(2, reference.n);
        Substitution.StaticElement after =
                assertInstanceOf(Substitution.StaticElement.class, substitution.elements[2]);
        assertEquals("-after", after.value);
        assertEquals("before-b-after",
                substitution.evaluate(matcher("(a)(b)", "ab"), null, null));
    }

    @Test
    void parsesConditionBackReference() {
        Substitution substitution = parse("x%2y");

        assertEquals(3, substitution.elements.length);
        Substitution.RewriteCondBackReferenceElement reference =
                assertInstanceOf(Substitution.RewriteCondBackReferenceElement.class, substitution.elements[1]);
        assertEquals(2, reference.n);
        assertEquals("xb-y", substitution.evaluate(null, matcher("(a)(b)", "ab"), null));
    }

    @Test
    void parsesRuleAndConditionBackReferencesInOrder() {
        Substitution substitution = parse("$1-%1");

        assertEquals(3, substitution.elements.length);
        assertEquals("R-C", substitution.evaluate(
                matcher("(R)", "R"), matcher("(C)", "C"), resolver(noMaps())));
    }

    @Test
    void consumesOnlyOneDigitForBackReferences() {
        Substitution rule = parse("$12");
        assertEquals(2, rule.elements.length);
        Substitution.RewriteRuleBackReferenceElement ruleReference =
                assertInstanceOf(Substitution.RewriteRuleBackReferenceElement.class, rule.elements[0]);
        assertEquals(1, ruleReference.n);
        Substitution.StaticElement ruleTrailing =
                assertInstanceOf(Substitution.StaticElement.class, rule.elements[1]);
        assertEquals("2", ruleTrailing.value);
        assertEquals("R2", rule.evaluate(matcher("(R)", "R"), null, null));

        Substitution cond = parse("%34");
        assertEquals(2, cond.elements.length);
