package io.undertow.servlet.compat.rewrite;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;

/**
 * Tests for {@link Substitution#parse(Map)}.
 */
class SubstitutionParseTests {

    private static Map<String, RewriteMap> noMaps() {
        return Collections.emptyMap();
    }

    private static Substitution parse(String sub) {
        return parse(sub, noMaps());
    }

    private static Substitution parse(String sub, Map<String, RewriteMap> maps) {
        Substitution substitution = new Substitution();
        substitution.setSub(sub);
        substitution.parse(maps);
        return substitution;
    }

    private static RewriteMap lookupMap(final Map<String, String> values) {
        return new RewriteMap() {
            @Override
            public String setParameters(String params) {
                return null;
            }

            @Override
            public String lookup(String key) {
                return values.get(key);
            }
        };
    }

    private static Resolver resolver(final Map<String, String> values) {
        return new Resolver() {
            @Override
            public String resolve(String key) {
                return values.get(key);
            }

            @Override
            public String resolveEnv(String key) {
                return values.get("ENV:" + key);
            }

            @Override
            public String resolveSsl(String key) {
                return values.get("SSL:" + key);
            }

            @Override
            public String resolveHttp(String key) {
                return values.get("HTTP:" + key);
            }

            @Override
            public boolean resolveResource(int type, String name) {
                return false;
            }
        };
    }

    private static Matcher matcher(String regex, String input) {
        return Pattern.compile(regex).matcher(input);
    }

    @Test
    void emptySubstitutionProducesNoElements() {
        Substitution substitution = parse("");

        assertEquals(0, substitution.elements.length);
        assertEquals("", substitution.evaluate(null, null, null));
    }

    @Test
    void parsesStaticTextOnly() {
        Substitution substitution = parse("hello world");

        assertEquals(1, substitution.elements.length);
        Substitution.StaticElement element =
                assertInstanceOf(Substitution.StaticElement.class, substitution.elements[0]);
        assertEquals("hello world", element.value);
        assertEquals("hello world", substitution.evaluate(null, null, null));
    }

    @Test
    void parsesRuleBackReference() {
        Substitution substitution = parse("$3");

        assertEquals(1, substitution.elements.length);
        Substitution.RewriteRuleBackReferenceElement element =
                assertInstanceOf(Substitution.RewriteRuleBackReferenceElement.class, substitution.elements[0]);
        assertEquals(3, element.n);
        assertEquals("c", substitution.evaluate(matcher("(a)(b)(c)", "abc"), null, null));
    }

    @Test
    void parsesStaticTextAroundRuleBackReference() {
        Substitution substitution = parse("before-$2-after");

        assertEquals(3, substitution.elements.length);
        Substitution.StaticElement before =
                assertInstanceOf(Substitution.StaticElement.class, substitution.elements[0]);
        assertEquals("before-", before.value);
        Substitution.RewriteRuleBackReferenceElement reference =
                assertInstanceOf(Substitution.RewriteRuleBackReferenceElement.class, substitution.elements[1]);
        assertEquals(2, reference.n);
        Substitution.StaticElement after =
                assertInstanceOf(Substitution.StaticElement.class, substitution.elements[2]);
        assertEquals("-after", after.value);
        assertEquals("before-b-after",
                substitution.evaluate(matcher("(a)(b)", "ab"), null, null));
    }

    @Test
    void parsesConditionBackReference() {
        Substitution substitution = parse("x%2y");

        assertEquals(3, substitution.elements.length);
        Substitution.RewriteCondBackReferenceElement reference =
                assertInstanceOf(Substitution.RewriteCondBackReferenceElement.class, substitution.elements[1]);
        assertEquals(2, reference.n);
        assertEquals("xb-y", substitution.evaluate(null, matcher("(a)(b)", "ab"), null));
    }

    @Test
    void parsesRuleAndConditionBackReferencesInOrder() {
        Substitution substitution = parse("$1-%1");

        assertEquals(3, substitution.elements.length);
        assertEquals("R-C", substitution.evaluate(
                matcher("(R)", "R"), matcher("(C)", "C"), resolver(noMaps())));
    }

    @Test
    void consumesOnlyOneDigitForBackReferences() {
        Substitution rule = parse("$12");
        assertEquals(2, rule.elements.length);
        Substitution.RewriteRuleBackReferenceElement ruleReference =
                assertInstanceOf(Substitution.RewriteRuleBackReferenceElement.class, rule.elements[0]);
        assertEquals(1, ruleReference.n);
        Substitution.StaticElement ruleTrailing =
                assertInstanceOf(Substitution.StaticElement.class, rule.elements[1]);
        assertEquals("2", ruleTrailing.value);
        assertEquals("R2", rule.evaluate(matcher("(R)", "R"), null, null));

        Substitution cond = parse("%34");
        assertEquals(2, cond.elements.length);
        Substitution.RewriteCondBackReferenceElement condReference =
                assertInstanceOf(Substitution.RewriteCondBackReferenceElement.class, cond.elements[0]);
        assertEquals(3, condReference.n);
        Substitution.StaticElement condTrailing =
                assertInstanceOf(Substitution.StaticElement.class, cond.elements[1]);
        assertEquals("4", condTrailing.value);
        assertEquals("d4", cond.evaluate(null, matcher("(a)(b)(c)(d)", "abcd"), null));
    }

    @Test
    void parsesUnqualifiedServerVariable() {
        Substitution substitution = parse("%{REQUEST_URI}");

        assertEquals(1, substitution.elements.length);
        Substitution.ServerVariableElement element =
                assertInstanceOf(Substitution.ServerVariableElement.class, substitution.elements[0]);
        assertEquals("REQUEST_URI", element.key);
        assertEquals("/ctx/path",
                substitution.evaluate(null, null, resolver(Map.of("REQUEST_URI", "/ctx/path"))));
    }

    @Test
    void parsesEnvServerVariable() {
        Substitution substitution = parse("%{ENV:JAVA_HOME}");

        assertEquals(1, substitution.elements.length);
        Substitution.ServerVariableEnvElement element =
                assertInstanceOf(Substitution.ServerVariableEnvElement.class, substitution.elements[0]);
        assertEquals("JAVA_HOME", element.key);
        assertEquals("/java",
                substitution.evaluate(null, null, resolver(Map.of("ENV:JAVA_HOME", "/java"))));
    }

    @Test
    void parsesSslServerVariable() {
        Substitution substitution = parse("%{SSL:SSL_PROTOCOL}");

        assertEquals(1, substitution.elements.length);
        Substitution.ServerVariableSslElement element =
                assertInstanceOf(Substitution.ServerVariableSslElement.class, substitution.elements[0]);
        assertEquals("SSL_PROTOCOL", element.key);
        assertEquals("TLSv1.3",
                substitution.evaluate(null, null, resolver(Map.of("SSL:SSL_PROTOCOL", "TLSv1.3"))));
    }

    @Test
    void parsesHttpServerVariable() {
        Substitution substitution = parse("%{HTTP:User-Agent}");

        assertEquals(1, substitution.elements.length);
        Substitution.ServerVariableHttpElement element =
                assertInstanceOf(Substitution.ServerVariableHttpElement.class, substitution.elements[0]);
        assertEquals("User-Agent", element.key);
        assertEquals("test-agent",
                substitution.evaluate(null, null, resolver(Map.of("HTTP:User-Agent", "test-agent"))));
    }

    @Test
    void typedServerVariableKeyMayContainColon() {
        Substitution substitution = parse("%{HTTP:X:Y}");

        Substitution.ServerVariableHttpElement element =
                assertInstanceOf(Substitution.ServerVariableHttpElement.class, substitution.elements[0]);
        assertEquals("X:Y", element.key);
    }

    @Test
    void parsesMapLookupWithoutDefault() {
        RewriteMap map = lookupMap(Map.of("key", "value"));
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("mymap", map);

        Substitution substitution = parse("${mymap:key}", maps);

        assertEquals(1, substitution.elements.length);
        Substitution.MapElement element =
                assertInstanceOf(Substitution.MapElement.class, substitution.elements[0]);
        assertSame(map, element.map);
        assertEquals("key", element.key);
        assertNull(element.defaultValue);
        assertEquals("value", substitution.evaluate(null, null, null));
    }

    @Test
    void parsesMapLookupWithDefault() {
        RewriteMap map = lookupMap(Map.of());
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("mymap", map);

        Substitution substitution = parse("${mymap:missing|fallback}", maps);

        Substitution.MapElement element =
                assertInstanceOf(Substitution.MapElement.class, substitution.elements[0]);
        assertSame(map, element.map);
        assertEquals("missing", element.key);
        assertEquals("fallback", element.defaultValue);
        assertEquals("fallback", substitution.evaluate(null, null, null));
    }

    @Test
    void mapLookupResultTakesPrecedenceOverDefault() {
        RewriteMap map = lookupMap(Map.of("present", "actual"));
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("mymap", map);

        Substitution substitution = parse("${mymap:present|fallback}", maps);

        assertEquals("actual", substitution.evaluate(null, null, null));
    }

    @Test
    void mapKeyMayContainColonAndDefaultMayContainPipe() {
        RewriteMap map = lookupMap(Map.of("a:b", "value"));
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("mymap", map);

        Substitution substitution = parse("${mymap:a:b|d1|d2}", maps);

        Substitution.MapElement element =
                assertInstanceOf(Substitution.MapElement.class, substitution.elements[0]);
        assertEquals("a:b", element.key);
        assertEquals("d1|d2", element.defaultValue);
    }

    @Test
    void parsesCombinedSubstitutionInOrder() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("mymap", lookupMap(Map.of()));

        Substitution substitution =
                parse("pre-$1-%2-%{HTTP:X}-${mymap:k|fallback}end", maps);

        assertEquals(9, substitution.elements.length);
        assertEquals("pre-R-C-H-fallbackend", substitution.evaluate(
                matcher("(R)", "R"),
                matcher("(C)", "C"),
                resolver(Map.of("HTTP:X", "H"))));
    }

    @Test
    void rejectsTrailingDollar() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("abc$"));
        assertEquals("abc$", exception.getMessage());
    }

    @Test
    void rejectsTrailingPercent() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("abc%"));
        assertEquals("abc%", exception.getMessage());
    }

    @Test
    void rejectsDollarFollowedByNonDigitWithoutMapSyntax() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("$name"));
        assertEquals("$name", exception.getMessage());
    }

    @Test
    void rejectsMapLookupWithoutColon() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("${map}"));
        assertEquals("${map}", exception.getMessage());
    }

    @Test
    void rejectsMapLookupWithoutClosingBrace() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("${map:key"));
        assertEquals("${map:key", exception.getMessage());
    }

    @Test
    void rejectsUnknownMapName() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("${missing:key}", noMaps()));
        assertEquals("${missing:key}: No map: missing", exception.getMessage());
    }

    @Test
    void rejectsMapDefaultAfterClosingBrace() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("m", lookupMap(Map.of("a", "value")));

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("${m:a}|x", maps));
        assertEquals("${m:a}|x", exception.getMessage());
    }

    @Test
    void rejectsMapDefaultBeforeMapSeparatorColon() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("a|b", lookupMap(Map.of("c", "value")));

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> parse("${a|b:c}", maps));
        assertEquals("${a|b:c}", exception.getMessage());
    }

    @Test
    void rejectsPercentFollowedByTextWithoutBraces() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("abc%foo"));
        assertEquals("abc%foo", exception.getMessage());
    }

    @Test
    void rejectsServerVariableWithoutClosingBrace() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("%{ENV"));
        assertEquals("%{ENV", exception.getMessage());
    }

    @Test
    void rejectsUnknownServerVariableType() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("%{FOO:bar}"));
        assertEquals("%{FOO:bar}: Bad type: FOO", exception.getMessage());
    }

    @Test
    void rejectsTypedServerVariableWithColonAfterClosingBrace() {
        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> parse("%{ENV}x:y"));
        assertEquals("%{ENV}x:y", exception.getMessage());
    }
}
