    void createInstanceRejectsInstancesOfTheWrongType() throws Exception {
        AnnotatedEndpointFactory factory = AnnotatedEndpointFactory.create(StringMessageEndpoint.class,
                EncodingFactory.DEFAULT, NO_PATHS);

        assertThrows(IllegalArgumentException.class,
                () -> factory.createInstance(new SimpleInstanceHandle<>(new EndpointWithoutAnnotatedMethods())));
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private static EncodingFactory factoryWithDecoders(final Class<?> textType, final Class<?> binaryType) {
        Map<Class<?>, List<InstanceFactory<? extends Encoder>>> noEncoders = Collections.emptyMap();
        Map<Class<?>, List<InstanceFactory<? extends Decoder>>> textDecoders = new HashMap<>();
        Map<Class<?>, List<InstanceFactory<? extends Decoder>>> binaryDecoders = new HashMap<>();
        if (textType != null) {
            textDecoders.put(textType, Collections.<InstanceFactory<? extends Decoder>>emptyList());
        }
        if (binaryType != null) {
            binaryDecoders.put(binaryType, Collections.<InstanceFactory<? extends Decoder>>emptyList());
        }
        return new EncodingFactory(noEncoders, binaryDecoders, noEncoders, textDecoders);
    }

    private static BoundMethod boundMethod(final AnnotatedEndpointFactory factory, final String name) throws Exception {
        return (BoundMethod) readField(factory, name);
    }

    private static Object readField(final Object target, final String name) throws Exception {
        Class<?> type = target.getClass();
        while (type != null) {
            try {
                Field field = type.getDeclaredField(name);
                field.setAccessible(true);
                return field.get(target);
            } catch (NoSuchFieldException e) {
                type = type.getSuperclass();
            }
        }
        throw new NoSuchFieldException(name + " on " + target.getClass());
    }

    private static String boundMethodName(final BoundMethod boundMethod) throws Exception {
        return ((Method) readField(boundMethod, "method")).getName();
    }

    private static Class<?> boundMethodDeclaringClass(final BoundMethod boundMethod) throws Exception {
        return ((Method) readField(boundMethod, "method")).getDeclaringClass();
    }

    private static Class<?> messageType(final BoundMethod boundMethod) throws Exception {
        return (Class<?>) readField(boundMethod, "messageType");
    }

    private static boolean decoderRequired(final BoundMethod boundMethod) throws Exception {
        return (Boolean) readField(boundMethod, "decoderRequired");
    }

    private static long maxMessageSize(final BoundMethod boundMethod) throws Exception {
        return (Long) readField(boundMethod, "maxMessageSize");
    }

    private static <T> T assertNotNullAndGet(final T value) {
        assertNotNull(value);
        assertSame(value, value);
        return value;
    }

    private static final class SimpleInstanceHandle<T> implements InstanceHandle<T> {

        private final T instance;

        private SimpleInstanceHandle(final T instance) {
            this.instance = instance;
        }

        @Override
        public T getInstance() {
            return instance;
        }

        @Override
        public void release() {
        }
    }
}
